quests[60658] = { id = 60658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endloser Appetit" }
quests[60659] = { id = 60659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lichtverteidigung" }
quests[60660] = { id = 60660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testflug", description = "Die hier kommen an meine Arme... und dann habe ich Flügel, ja?\n\nDann springe ich von der Klippe. Und fliege!\n\nSeht Ihr zu?", sourceObjective = "Beobachtet Kowalskos' Testflug.", completion = "Hm... So nicht. Was noch, was noch...", sourceObjectiveStatus = "unverified-source-field" }
quests[60661] = { id = 60661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sterbende Träume", description = "Wir haben schon so viele verloren... und die hier ist etwas Besonderes.\n\n<Mondbeere sieht Euch entschlossen an. Ihre Stimme klingt seltsam förmlich und hat einen strikten Befehlston.>\n\nKommt, {name}. Wir tragen sie zum Pfad der Wiedergeburt und bitten die Königin, sie zu retten.\n\nBeeilt Euch mit Euren Vorbereitungen. Wir haben nicht viel Zeit.", sourceObjective = "Bringt Yseras Wildsamen zum Herz des Waldes.", completion = "Seid gegrüßt, Fremdling. Ihr kommt zu einer... interessanten Zeit.\n\n<Herne schnaubt und lacht.>\n\nUnd in ebenso interessanter Gesellschaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[60669] = { id = 60669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grund zur Ablenkung", sourceObjective = "Sprecht mit Lor'themar Theron oben auf der Feste Grommash in Orgrimmar.", completion = "Auch wenn wir nach Thrall und Baine suchen müssen, dürfen wir dabei den Schutz unserer Bürger und Verbündeten nicht vernachlässigen.\n\nZu diesem Zweck habe ich mich der Hilfe derjenigen versichert, die Erfahrung im Umgang mit der Geißel haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[60670] = { id = 60670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr des Kreuzzugs", description = "Ich habe den unerbittlichn Vormarsch der Geißel mit eigenen Augen gesehen. Es ist nur eine Frage der Zeit, bis sie an unseren Toren rütteln.\n\nDas Schicksal, das Silbermond ereilt hat, darf sich nie wiederholen.\n\nDie Todesritter der Schwarzen Klinge haben sich erboten, gegen die Bedrohung zu kämpfen, aber selbst sie werden Verstärkung benötigen.\n\nDer Argentumkreuzzug ist erneut dem Ruf gefolgt. Ich bitte Euch, ihm zur Seite zu stehen, um unser Volk zu schützen, {name}.\n\nIhr Kommandant erwartet Eure Ankunft.", sourceObjective = "Sprecht mit Kommandant Throgg im Tal der Stärke in Orgrimmar.", completion = "<Kommandant Throgg knurrt.>\n\nIhr müsst es sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60671] = { id = 60671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Opfer, die wir bringen müssen", description = "Beeilt Euch! Wir können die Animazapfen, die wir gesammelt haben, zu Derawyns Rettung verwenden.\n\nIch weiß, dass sie für die Wildsamen gedacht sind... aber wir dürfen nicht zulassen, dass diese Monster uns noch jemanden wegnehmen.", sourceObjective = "Verwendet die geborgenen Animazapfen, um Wagenmeisterin Derawyn zu retten.", completion = "Da ist das Herz des Hains.\n\nWir müssen es zurückbekommen... für all diejenigen, die gefallen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[60673] = { id = 60673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verräter", description = "Nun, sieht so aus, als ob ich Euch jetzt hereinlassen sollte.\n\nIch kann aber nicht versprechen, dass Mateo besonders freundlich sein wird. Ich hatte meinen alten Boss lieber, aber sagt ihm das nicht.\n\nIch frage mich, was aus ihr geworden ist. Denathrius hat ziemlich aufgebracht gewirkt, als sie das letzte Mal miteinander gesprochen haben.\n\nSei's drum, lasst mich die Tür für Euch öffnen.", sourceObjective = "Tötet Sündenhüter Mateo und nehmt ihm seine Spiegelscherbe ab.", progress = "Habt Ihr Mateos Spiegelscherbe?", completion = "Er war so vielversprechend bei der Ausübung seiner Pflichten.\n\nIch nehme an, dem Machtversprechen konnte er einfach nicht widerstehen. Doch jetzt ist nicht der richtige Zeitpunkt, über solche Dinge nachzugrübeln, {name}. Lasst uns weitermachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60709] = { id = 60709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz zurückholen", description = "Dunkelheit umklammert das Herz von Droman Krelnor, so wie er das Herz des Hains umklammert.\n\nAnima wird dem Herz entzogen wie Nektar aus reifen Früchten. Das muss aufgehalten werden.\n\nBösartige Magie versperrt den Weg. Anima in Gefahr, Anima die Erlösung.\n\nFleht Te'zan an. Eine alte Seele, randvoll mit Anima, der Funken, der unsere Hoffnung entzündet.", sourceObjective = "Sprecht mit Te'zan, um die Barriere des Dromanen zu durchbrechen, und stellt dann Droman Krelnor.", completion = "Wir haben so viel verloren. Warum sollte irgendjemand so etwas tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[60721] = { id = 60721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Anima muss fließen", description = "Das Gerät, das Ihr hier seht, kann verwendet werden, um Anima zu den dürstenden Vierteln zu leiten und unseren Leuten zu helfen.\n\nJedes Viertel, das seinen Animastrom zurückerhält, wird wieder aufblühen. Ihr werdet jene finden, die Euch auf Euren Reisen behilflich sein werden oder vielleicht stoßt Ihr sogar auf neue Herausforderungen, die Euch erwarten.\n\nSobald Ihr etwas Anima in unser Sanktum gebracht habt, leitet sie mit diesem Gerät zu einem Viertel. Dann seht Ihr selbst das Ergebnis.", sourceObjective = "Benutzt den Animaleiter, um Anima an einen Ort in Revendreth zu kanalisieren.", completion = "Anima fließt wieder in ein Viertel. Ihr solltet in regelmäßigen Abständen zum Gerät zurückkehren und noch mehr kanalisieren.\n\nWenn Ihr Anima sammelt und sie nach Revendreth kanalisiert, werden die Ströme an Stärke zunehmen. Obwohl sie im Augenblick nicht lange anhalten werden, solltet Ihr irgendwann den Strom soweit gestärkt haben, dass eine dauerhafte Verbindung entsteht.\n\nDa Anima endlich wieder in unsere Länder strömt, ist es nur eine Frage der Zeit, bis wir ganz Revendreth unter unserem Banner vereinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60722] = { id = 60722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht für den Turm", description = "Mithilfe dieses Geräts wird Anima zu unseren Türmen in ganz Maldraxxus kanalisiert. Dadurch werden unsere dort stationierten Truppen verstärkt.\n\nAuch wenn Ihr ihre Hilfe vielleicht ganz nützlich findet, solltet Ihr bedenken, dass die Anima auch die Aufmerksamkeit unserer Feinde erregen könnte.\n\nVerwendet das Gerät, um unsere Animavorräte zu einem der Türme zu leiten. Dann werdet Ihr bald erleben, wozu wahre Macht imstande ist.", sourceObjective = "Benutzt den Animaleiter, um Anima an einen Ort in Maldraxxus zu kanalisieren.", completion = "Ja, ja! Ich spüre den Animafluss. Ihr solltet regelmäßig zu dem Gerät zurückkehren und noch mehr kanalisieren.\n\nWenn Ihr mehr Anima sammelt und zu einem Turm kanalisiert, wird seine Verbindung zu unserem Sanktum immer stärker. Irgendwann könnt Ihr die Kanalisierung verstärken, um eine dauerhafte Verbindung herzustellen.\n\nWenn genug Anima durch ganz Maldraxxus fließt, werden unsere Armeen unaufhaltsam sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[60723] = { id = 60723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die durstigen Wurzeln", description = "Dieses Gerät kann die Wurzeln unseres großen Blätterdaches mit Anima tränken. Die Äste sehnen sich danach.\n\nJeder große Stamm, den wir mit Anima füllen, erblüht aufs Neue. Unter ihren schützenden Zweigen findet Ihr Hilfe und im Schatten erwarten Euch neue Herausforderungen.\n\nBringt nun dem Sanktum neue Anima und lenkt sie mit dem Gerät hinaus in den Wald. Lasst die Blüten wieder gedeihen.", sourceObjective = "Benutzt den Animaleiter, um Anima an einen Ort im Ardenwald zu kanalisieren.", completion = "Die Wurzeln sind wieder von Anima erfüllt. Ihr solltet regelmäßig zu dem Gerät zurückkehren und weitere Anima kanalisieren, damit sich alle daran laben.\n\nWenn Ihr Anima sammelt und kanalisiert, werden die Ströme allmählich stärker. Obwohl sie noch nicht lange anhalten werden, werdet Ihr irgendwann die Kanalisierung verstärken können, um eine dauerhafte Verbindung herzustellen.\n\nBald schon werden alle ihre Blüten öffnen und uns mit ihrer Pracht erfreuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60724] = { id = 60724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzlos", description = "So viele meiner Freunde sind in den Zyklus zurückgekehrt... nur wegen dieser seltsamen Masken.\n\nWarum haben sie meine Freunde an sich gerissen? Welchen Sinn hatte es, das Herz meines Hains zu zerstören?\n\nIhr müsst nach Tirna Vaal zurückkehren und Dromanin Tashmur berichten, was hier geschehen ist.\n\nIrgendwann werde ich mich auf den Weg dorthin machen. Ich... brauche nur etwas Zeit, um mich zu verabschieden.", sourceObjective = "Kehrt zu Dromanin Tashmur in Tirna Vaal zurück.", completion = "Schatten zeichnen sich über dem Wald ab, Vorboten der kommenden Tragödie.\n\nDer Fluss des Schicksals fließt schnell, seine Ströme unaufhaltsam. Wohin sie führen... kann niemand erahnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60725] = { id = 60725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einsatzberichte", description = "Wir können nicht vorhersehen, wo und wann die Geißel zuschlagen wird.\n\nUm eine Verteidigung aufzubauen, hat der Argentumkreuzzug an mehreren wichtigen Orten Außenposten errichtet, von denen wir aber noch keine Nachricht erhalten haben.\n\nSucht meine Feldoffiziere entlang der südlichen Straße auf. Ich erwarte einen vollständigen Bericht, wenn Ihr zurückkehrt.", sourceObjective = "Sammelt Berichte von Offizieren in Durotar und dem Brachland.", progress = "Verstärkung? Dem Licht sei Dank!", completion = "Die Lage scheint verheerender zu sein, als wir dachten...\n\nKommandant Throgg muss davon erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[60727] = { id = 60727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Botschaft aus Eiskrone", description = "Unsere Streitkräfte in Nordend haben eine Nachricht geschickt. Justiziarin Treuherz erbittet unsere sofortige Hilfe.\n\nWir müssen dieser Aufforderung umgehend nachkommen, egal welche Schrecken uns in Eiskrone erwarten.\n\n<Ein/Eine:c> {class} wie Ihr würde unsere Chancen auf dem Schlachtfeld wesentlich verbessern.\n\nIhr habt mein Wort, dass Orgrimmar in Eurer Abwesenheit beschützt wird.\n\nDie Schlacht ruft, {name}. Ich gehe davon aus, dass Ihr bereit seid.", sourceObjective = "Meldet Euch bei Justiziarin Mariel Treuherz am Argentumturnierplatz in Eiskrone.", completion = "Ihr kommt genau zur rechten Zeit. Kommandant Throgg hat Euch in den höchsten Tönen gelobt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60732] = { id = 60732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub unterbrechen", description = "<Die gequälte Verkörperung der Seele vor Euch brennt mit einer magmatischen Flamme. Für welchen Zweck sie auch immer in diesem Kessel gedacht war, er wurde erfüllt.\n\nDie völlige Ignoranz gegenüber der verbliebenen Hülle der Seele ist beunruhigend. Es wird so weitergehen, wenn nicht etwas geschieht.\n\nSchickt den Bewohnern von Zovaals Kessel eine Nachricht.>", sourceObjective = "Unterbrecht die Anstrengungen der Schlundgebundenen in Zovaals Kessel.", completion = "Freut Euch über das, was Ihr erreicht habt, aber vergesst die Tragweite Eurer Handlungen nicht.\n\nEr hat alles im Blick.", sourceObjectiveStatus = "unverified-source-field" }
quests[60733] = { id = 60733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorne und mittig", sourceObjective = "Ermächtigt die Rune der Macht am Sitz des Primus.", progress = "Kommt! Der Sieg wartet auf uns!", completion = "Blut und Donner, wir werden den Feind zermalmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60735] = { id = 60735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger im Paradies", description = "Ich habe mir über Eure Anwesenheit hier so meine Gedanken gemacht, {name}.\n\nEs ist wohl eindeutig, dass Ihr kein gewöhnlicher Neuzugang aus Oribos seid. Ich weiß nicht, warum Ihr hier seid oder was Ihr zu erreichen sucht. Schon das ist etwas, das ich noch nie erlebt habe.\n\nIhr müsst verstehen... Individuen kommen nicht so einfach aus einer Laune heraus in die Bastion. Dieses Schicksal muss man sich verdienen und die tatsächlich Auserwählten verfügen über einzigartige Talente für diese Existenz.\n\nAlso... Ich frage Euch... Warum seid Ihr wirklich hier?", sourceObjective = "Beantwortet Kleias Frage.", completion = "<Kalisthene schaut zu Euch hinab.>\n\nWir haben Euch gehört, Sterblicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[60736] = { id = 60736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quest 2", sourceObjective = "Öffnet die Tür zum Sitz des Primus.", sourceObjectiveStatus = "unverified-source-field" }
quests[60737] = { id = 60737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tür ins Unbekannte", description = "Ihr habt die letzte Rune ermächtigt? Das könnte das Blatt in diesem Kampf wenden!\n\nÖffnet die Tür, {name}! Wir halten den Feind zurück, so lange wir können!", sourceObjective = "Öffnet die Tür zum Sitz des Primus.", completion = "<Die Runenklinge leuchtet heller, als Ihr Euch einem alten Steinaltar nähert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[60738] = { id = 60738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg zum Winterschlafbecken", description = "So einen Wildsamen habe ich noch nie gesehen. Selbst diejenigen, die sich in der Vergangenheit mit ihren Hütern verbanden, manifestierten noch nie solche Alpträume.\n\nAndererseits hatten wir auch noch nie <einen lebenden Sterblichen/eine lebende Sterbliche> in unserer Mitte.\n\nWir müssen diesen Wildsamen zum Winterschlafbecken bringen. Dort kann er die Pflege und Aufmerksamkeit erhalten, die er braucht.\n\nIch werde ihn in die Geisterwiege legen. Könnt Ihr Niya bitten, Euch zu begleiten?\n\nDie arme Sylvar weiß seit dem Fall ihres Hains nichts mit sich anzufangen. Es würde ihr guttun.", sourceObjective = "Rekrutiert Niya, damit sie Euch hilft, den Wildsamen zum Winterschlafbecken zu bringen.", completion = "Es überrascht mich, dass ein Wildsamen dazu in der Lage sein sollte, derartige Alpträume hervorzubringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60739] = { id = 60739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwieriges Publikum" }
quests[60759] = { id = 60759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammte Eindringlinge", description = "Es ist unbedingt erforderlich, dass diese Berichte Kommandant Throgg erreichen, aber wir können kaum noch das Wegekreuz verteidigen.\n\nVor Eurer Abreise bitte ich Euch, uns zu helfen, die Zahlen der Diener der Geißel zu dezimieren. Das könnte uns die Atempause verschaffen, die wir benötigen.", sourceObjective = "Tötet 6 Kultisten und 4 blutrünstige Ghule am Wegekreuz.", completion = "Ihr habt meinen Dank, {class}. Wir werden all unsere Kraft benötigen, um die Geißel zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[60761] = { id = 60761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der Geißel", description = "Bringt diese Berichte zu Kommandant Throgg. Er muss über das volle Ausmaß der Bedrohung informiert werden, der wir ausgesetzt sind.\n\nWenn es uns nicht gelingt, die Stellung gegen die Geißel zu halten... dann möge das Licht uns allen beistehen.", sourceObjective = "Bringt Leutnant Altheras Bericht zu Kommandant Throgg im Tal der Stärke in Orgrimmar.\n\nBereitgestellter Gegenstand:", completion = "Ich werde diesen Bericht an den Lordregenten weitergeben. Ich fürchte, das ist erst der Anfang.\n\nAus Eiskrone erreichte uns eine Botschaft. Die Dunkelheit regt sich, und Eure Kraft ist erforderlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[60762] = { id = 60762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todespartikel", description = "Ich habe einen Auftrag für Euch, <Schlundgänger/Schlundgängerin>.\n\nSeelen, die man für geeignet hält, unter den Schlundgebundenen zu dienen, werden bis auf ihre reinste Essenz zerlegt. Die so entstandene Kreatur bildet einen schwarzen Schatten, ohne jeglichen eigenen Willen.\n\nDas ist ein tragisches Ende.\n\nIch möchte diesen Prozess besser verstehen. Was könnte bei einer Seele einen solchen Wandel verursachen?\n\nFragmente zerbrochener Seelen regnen über der Wiege des Ruins herab. Bringt mir einige davon, damit ich mehr über unseren gemeinsamen Gegner erfahren kann.", sourceObjective = "Sammelt 10 Todespartikel in der Wiege des Ruins im Schlund.", completion = "Es ist angesichts ihrer Herkunft eventuell... ethisch fragwürdig, aus diesen Partikeln Nutzen zu ziehen.\n\nAber dieses Wissen kann sich als entscheidend für den Sieg über unsere Gegner erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60763] = { id = 60763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch die Blume", description = "Eine Botschaft des Primus von Maldraxxus, sagt Ihr? Wir haben nichts von ihm gehört, seit... Nun, es ist lange her.\n\nEs handelt sich hier nicht um einen Streich, oder? Die Königin hat keine Zeit für Streiche. Aber ich schon!\n\n<Mondbeere beugt sich zu Euch heran und flüstert.>\n\nUnd ich glaube, für diesen brauchen wir noch eine weitere Lilie.\n\n<Mondbeere zwinkert.>\n\nLasst mich einen Blick auf diese Botschaft werfen. Ihr bringt diese letzte Nachtlilie zu Federleicht und dann unterhalten wir uns.", sourceObjective = "Helft Mondbeere und Federleicht.", completion = "Ich hoffe, Eure Ankunft im Ardenwald ist ein Zeichen dafür, dass uns bessere Zeiten bevorstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60764] = { id = 60764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besänftigendes Lied", description = "Ich fliege voraus zum Winterschlafbecken und überzeuge Dromanin Aliothe davon, uns zu helfen. Wenn Ihr mit Niya eintrefft, wird sie hoffentlich schon zugestimmt haben.\n\nDieser Wildsamen scheint sich in Eurer Gegenwart wohlzufühlen, also müsst Ihr dicht bei ihm bleiben.\n\nNiya muss dem Wildsamen außerdem etwas vorsingen, damit er ruhig bleibt... sonst könnten die Alpträume zurückkehren.\n\nSpriggans lieben es, uns bei unseren Liedern zu unterbrechen, also haltet nach ihnen Ausschau.\n\nSagt mir Bescheid, wenn Ihr bereit zum Aufbruch seid.", sourceObjective = "Reist mit Niya, um den Wildsamen zum Winterschlafbecken zu bringen.", progress = "Wie merkwürdig, dass so ein kleiner Wildsamen so viel Ärger verursachen kann...", completion = "Es ist schön, Euch wiederzusehen. Die Wilde Jagd könnte Eure Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60765] = { id = 60765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allheilmittel", description = "Viele Überlebende aus dem Haus der Seuchen benötigen noch immer Hilfe. Ihr Leiden macht mich traurig.\n\n<Schlundgänger/Schlundgängerin>, ich würde alles tun, um ihnen zu helfen. Auch, wenn wir nur einige retten können, ist das besser als nichts.\n\nBitte helft mir, sie zu heilen!", sourceObjective = "Verwendet Rosenpustels regenerative Häutung, um 15 seuchengeplagte Überlebende zu heilen.", completion = "Ihr und Rosenpustel habt gut daran getan, den Überlebenden des Hauses der Seuchen zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60766] = { id = 60766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammte Eindringlinge", description = "Bevor Ihr abreist... Wir brauchen dringend Verstärkung.\n\nDiese Berichte müssen Kommandant Gregor erreichen. Aber wenn Ihr uns vorher helfen würdet, die Anzahl der Diener der Geißel zu dezimieren, würde uns das eine dringend benötigte Atempause verschaffen.", sourceObjective = "Tötet 12 Diener der Geißel in der Umgebung.", completion = "Danke, {class}. Wir werden in den kommenden Tagen alle Kraft zusammennehmen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60767] = { id = 60767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der Geißel", description = "Bringt meinen Bericht zu Kommandant Gregor. Er muss darüber informiert werden, womit wir es zu tun haben.\n\nDie Zahl der Diener der Geißel nimmt zu, und wenn sie nicht wieder zurückgeht... dann möge das Licht uns allen beistehen.", sourceObjective = "Bringt Leutnant Vernons Bericht zu Kommandant Gregor im Handelsdistrikt von Sturmwind.\n\nBereitgestellter Gegenstand:", completion = "Ich werde dafür sorgen, dass König Graumähne und der Lordkommandant diese Berichte erhalten, obwohl ich fürchte, dass dies erst der Anfang ist.\n\nDieser Kurier hat mir gerade verheerende Neuigkeiten aus Eiskrone überbracht.\n\nOffenbar sind wir nicht die Einzigen, die angegriffen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[60770] = { id = 60770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerquetscht und abgefackelt" }
quests[60775] = { id = 60775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein angemessener Tod", description = "An diesem elenden Ort zu überleben war schwierig, aber ich muss gestehen... Es hat mir Freude bereitet, ein paar Schlundgebundenen einen angemessenen Tod zu bereiten.\n\nDie Seelenschmiede in Zovaals Kessel gehören zu den grausamsten Dienern, die der Kerkermeister beschäftigt. Es bereitet mir Genugtuung, ihre Kerne in genau den Schmieden zu entsorgen, die sie unterhalten.\n\nDas hat natürlich den zusätzlichen Vorteil, dass die Waffenproduktion vorübergehend verlangsamt wird, falls Ihr eine sachlichere Rechtfertigung für Eure Taten benötigt.", sourceObjective = "Werft 5 seelengeschmiedete Kerne in die Seelenschmieden in Zovaals Kessel im Schlund.", completion = "Fragt mich das nächste Mal, wie man eine Stampede von Schlundratten über eine Klippe jagt. Das ist immer wieder unterhaltsam.", sourceObjectiveStatus = "unverified-source-field" }
quests[60778] = { id = 60778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildsamenrettung", description = "<Federleicht überprüft seine Notizen.>\n\nMal sehen... Da war ein Gesuch um Hilfe wegen eines Wildsamens in Gefahr und... irgendetwas mit einem Ei? Die ursprüngliche Notiz war nicht gerade eindeutig, aber der Fae, der das geschickt hat... Ah! Es war wieder mal Korenth.\n\nNun ja, wir werden schon herausfinden, wo das Problem liegt!\n\nIch fliege vor und suche nach ihm. Folgt Ihr einfach dem Pfad.", sourceObjective = "Helft Korenth, den Wildsamen zurückzuholen.", progress = "Ihr habt überlebt!", completion = "Das war vielleicht ein Spaß! Ihr hattet den Vogel schon so weit, dass er ein Nest baut und Junge aufzieht!\n\nOh, diesen Lacher habe ich wirklich gebraucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[60785] = { id = 60785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeladene Gäste!" }
quests[60786] = { id = 60786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarmverteidigung" }
quests[60825] = { id = 60825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amateurspione", progress = "Euer Hof ist mit Spionen verseucht, Schlundgänger.\n\nTotenbeschwörer aus Maldraxxus, Amateure, die darauf hoffen, mich in einen Hinterhalt zu locken, während ich nicht auf der Hut bin.\n\nIch werde mir jeden vom Hals schaffen, der mir über den Weg läuft, aber ich würde es vorziehen, meine Aufmerksamkeit auf den Hof zu richten.\n\nBringt mir die Köpfe der verhüllten Totenbeschwörer, um zu beweisen, dass Ihr über eine gewisse Kompetenz in der Spionageabwehr verfügt.", completion = "Sie dachten, sie könnten die Herrin der Spione ausspionieren?\n\nDummköpfe bekommen, was sie verdienen." }
quests[60827] = { id = 60827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Anstrengungen vorantreiben", description = "Während die anderen Kreuzritter die Kontrolle über das Turniergelände zurückgewinnen, müssen wir beide vorwärtsdrängen.\n\nUnsere Streitkräfte hatten zuvor versucht, ein vorgeschobenes Lager weiter in der Eiskrone zu errichten, aber sie wurden überrannt.\n\nMit Euch an unserer Seite bin ich zuversichtlich, dass wir das Gebiet zurückerobern können.", sourceObjective = "Errichtet einen Stützpunkt auf dem Eisenwallbollwerk in Eiskrone.", completion = "Ausgezeichnete Arbeit, {name}.\n\nDie Vorbereitungen sind in vollem Gange. Bald wird der Stützpunkt ausgestattet und als Aufmarschgebiet nutzbar sein.\n\nDerweil gibt es noch andere Angelegenheiten, die Eure Aufmerksamkeit erfordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[60828] = { id = 60828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Stützpunkt", description = "Unsere Vorbereitungen sind abgeschlossen. Es ist Zeit, dass wir den Kampf zur Geißel tragen.\n\nDie Justiziarin hat mich gebeten, unsere Bemühungen im vorderen Lager zu leiten.\n\nTrefft mich dort und wir werden unsere Arbeit gemeinsam fortsetzen.", sourceObjective = "Trefft Kreuzfahrerin Renn im Argentumlager auf dem Eisenwallbollwerk in Eiskrone.", completion = "Unsere Späher berichten von erhöhter Aktivität beim Kult der Verdammten.\n\nIch glaube, es wird Zeit, dass wir genau herausfinden, was unsere fanatischen Freunde planen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60831] = { id = 60831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eines Markgrafen würdig", description = "Wir sind endlich bereit. Wir werden unseren großartigsten Trank erschaffen!\n\nIch weiß zwar nicht mehr, wofür der Trank gedacht war, aber ich bin so stolz auf Eure Fortschritte. Markgräfin Stradama wird von Euren Erfolgen begeistert sein!\n\nKommt nun. Zeigen wir ihr, was wir für sie gemacht haben!", sourceObjective = "Zeigt Markgräfin Stradama Euren Trank.", progress = "Na los, Lehrling!", completion = "Äh... Lehrling? Seid Ihr da? Ich fühle mich... komisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[60837] = { id = 60837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn von Aliothe" }
quests[60839] = { id = 60839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überreste der Wilden Jagd", description = "Die Wilde Jagd hält die Stellung gegen diese Monster, damit sie nicht die Straße zum Winterschlafbecken überrennen.\n\nZu viele meiner Jagdkameraden sind inzwischen von der dunklen Magie dieser verdrehten Masken besessen.\n\nAber mit Euch hier können wir das Blatt vielleicht wenden.\n\nHelft allen Jägern, die Ihr finden könnt, bevor unsere Gegner sie gegen uns aufhetzen.\n\nIch treffe Euch weiter unten in der Aue. Wenn wir unsere Kräfte bündeln, können wir diesen Kampf beenden.", sourceObjective = "Rettet 5 verwundete Verteidiger aus Soryns Aue.", completion = "Danke, dass Ihr meine Jagdkameraden gerettet habt. Wir werden Zeit haben, den in den Zyklus Zurückgekehrten unseren Respekt zu erweisen, wenn all dies vorbei ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[60840] = { id = 60840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offensive der Wilden Jagd" }
quests[60841] = { id = 60841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evakuierungseinsatz", description = "Unsere Truppen sind in Gefahr, und die Schuld liegt bei mir selbst. In dem Glauben, dass die Umgebung sicher sei, schickte ich eine kleine Gruppe los, um das verlassene Lager im Tal im Südwesten zu sichern.\n\nAber unsere Einsatzberichte waren veraltet oder falsch. Das Lager ist ein hoffnungsloser Fall. Wir müssen uns jetzt darauf konzentrieren, diejenigen zu retten, die ich dorthin geschickt hatte.\n\nGeht zum Lager und tut, was Ihr könnt, um unsere Verbündeten zu retten.", sourceObjective = "Rettet 6 Verbündete im Tal der Verlorenen Hoffnung. Tötet 6 Diener der Geißel in dem Gebiet.", completion = "Danke, {name}. Eure Bemühungen haben viele Leben gerettet.\n\nVon nun an werde ich dafür sorgen, dass unsere Späherberichte präzise und aktuell sind. Es scheint, dass die Bedrohungen, denen wir ausgesetzt sind, mit jedem Tag schlimmer werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[60842] = { id = 60842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lecker, Spriggans!" }
quests[60843] = { id = 60843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kult-Couture", description = "Obwohl unsere Späher die kultistischen Kräfte in Aldur'thar infiltrieren konnten, hat es sich als nahezu unmöglich erwiesen, sich nach Mord'rethar hineinzuschleichen.\n\nVielleicht ist es Zeit, andere Zugangsmethoden zu erforschen.\n\nBeginnt damit, die nahegelegenen Ritualkammern der Sekte zu untersuchen, vielleicht findet Ihr etwas Nützliches.", sourceObjective = "Holt eine Kapuze des Kollaborateurs und eine Robe des Kollaborateurs von den Kultisten in Aldur'thar.", progress = "Ihr habt etwas gefunden?", completion = "Dies sollte genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60844] = { id = 60844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugschule: Fallen mit Stil" }
quests[60855] = { id = 60855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormageddon" }
quests[60856] = { id = 60856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt ihn zu Fall", description = "Eine Monstrosität in der Nähe hat unsere Bemühungen, diese Aue zu räumen, zunichte gemacht.\n\nGemeinsam können wir sie zur Strecke bringen.\n\nWir beide stellen die Bestie. Zum richtigen Zeitpunkt werde ich der Jagd das Zeichen zum Sturmangriff geben.\n\nDie Wilde Jagd hat zu viele Verluste erlitten. Heute werden wir einen Sieg gegen diese Monster erringen!", sourceObjective = "Besiegt die verseuchte Bestie.", completion = "Gute Arbeit, {name}. Wir werden dadurch nicht den Sieg in diesem Krieg davontragen... aber wenigstens wird es uns im Kampf um Soryns Aue helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60857] = { id = 60857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir können nicht alle retten", description = "Ich bin angenehm überrascht, dass Ihr nicht in Stücke gerissen wurdet! Gut gemacht.\n\nAber jetzt befürchte ich, dass wir eine sehr viel ernsthaftere Aufgabe erledigen müssen.\n\nDie Winterkönigin hat angeordnet, dass die Anima des Herzholzhains eingesammelt wird und die Einwohner ihn verlassen müssen, während er verdorrt. Aber es werden nicht alle Wildsamen mitkommen können. Tatsächlich werden nur einige wenige von ihnen gerettet.\n\nWir werden Droman Krelnor die endgültige Liste bringen.", sourceObjective = "Bringt die Liste geretteter Wildsamen zu Droman Krelnor im Herzholzhain.", progress = "Geht weiter, Fremder.", completion = "<Droman Krelnor seufzt erschöpft, als er die kurze Wildsamenliste sieht.>\n\nZumindest ein paar können nach Tirna Vaal verlagert werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[60858] = { id = 60858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugschule: Auf und davon!" }
quests[60859] = { id = 60859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelen des Waldes", description = "Wenn Ihr für Lady Mondbeere einspringt, könnt Ihr vielleicht helfen!\n\nWagenmeisterin Derawyn begleitete ein paar von uns zu einem neuen Hain, als wir von einem Rudel hungriger Raubtiere angegriffen wurden! Der Wolf ist eine schnelle Seelengestalt, also konnte ich entkommen... aber ein paar der Kleinen hatten nicht so viel Glück. Sie werden wie Beutetiere gejagt!\n\nKommt! Sie sind nur ein Stück die Straße entlang!", sourceObjective = "Rettet die Seelen aus der Gefahr.", progress = "Na, das war ja aufregend.", completion = "Es ist eine Weile her, dass eine neue Seele in den Ardenwald gekommen ist, also ist jede kostbar, die schon hier ist.\n\nIch werde Lady Mondbeere erzählen, was Ihr alles in ihrem Namen geleistet habt. Vielleicht schenkt sie Euch zum Dank ja sogar ihre Gunst!", sourceObjectiveStatus = "unverified-source-field" }
quests[60861] = { id = 60861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse in den Schatten", description = "Obwohl wir die Ansammlungen der Kultisten in Mord'rethar beobachtet haben, konnten wir noch nicht herausfinden, welche Geheimnisse sich in den Kammern verbergen.\n\nNehmt diese Gewänder, macht Euch auf den Weg ins Innere Sanktum und seht, was Ihr entdecken könnt.\n\nDas könnte unsere einzige Chance sein, etwas über ihre Absichten zu erfahren, {name}.", sourceObjective = "Benutzt die Roben des Kollaborateurs und entdeckt, welche Geheimnisse sich in Mord'rethar verbergen.", progress = "Ihr habt etwas gefunden?", completion = "<Diese Neuigkeit ist sehr beunruhigend.>", sourceObjectiveStatus = "unverified-source-field" }
quests[60867] = { id = 60867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Nachricht von oben", sourceObjective = "Findet heraus, wo sich Heroldin Dalora aufhält. Vernichtet die Truppen der Geißel um die Eiskronenzitadelle herum.", progress = "Der Himmel über der Zitadelle mag gefährlich sein, aber wir müssen wissen, womit wir es zu tun haben.", completion = "Ihre Zahl ist vorübergehend verringert. Das ist unsere Chance, zuzuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60869] = { id = 60869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greifbare Hoffnung", description = "Ihr müsst Orgrimmar von dem, was wir aufgedeckt haben, berichten. Einer unserer Magier kann auf dem Turniergelände ein Portal für Euch öffnen.\n\nWir vom Argentumkreuzzug müssen als Bollwerk gegen die Geißel hierbleiben. Wenn Ihr uns weiterhin helfen wollt, werde ich dafür sorgen, dass Eure Fähigkeiten gut eingesetzt werden.\n\nMöge das Licht euch beschützen, {name}.", sourceObjective = "Errichtet ein Portal nach Orgrimmar auf dem Argentumturnierplatz. Überbringt die Neuigkeiten Lor'themar Theron auf Feste Grommash in Orgrimmar.", completion = "Das sind beunruhigende Neuigkeiten, {name}. Kaum zu glauben, dass Sylvanas sich bereitwillig mit einer solch dunklen Macht verbünden würde...", sourceObjectiveStatus = "unverified-source-field" }
quests[60871] = { id = 60871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greifbare Hoffnung", description = "Ihr müsst Sturmwind von dem, was wir aufgedeckt haben, berichten. Einer unserer Magier kann auf dem Turniergelände ein Portal für Euch öffnen.\n\nWir vom Argentumkreuzzug müssen als Bollwerk gegen die Geißel hierbleiben. Wenn Ihr uns weiterhin helfen wollt, werde ich dafür sorgen, dass Eure Fähigkeiten gut eingesetzt werden.\n\nMöge das Licht euch beschützen, {name}.", sourceObjective = "Errichtet ein Portal nach Sturmwind auf dem Argentumturnierplatz. Überbringt die Neugikeiten Genn Graumähne in der Löwenruh in Sturmwind.", completion = "Dies ist finstere Kunde, {name}. Es scheint, dass die Banshee sich mit einer Macht verbündet hat, die noch dunkler ist, als wir ahnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60872] = { id = 60872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gefährliche Ernte" }
quests[60881] = { id = 60881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritt der Wilden Jagd", description = "Dank Eurer Bemühungen haben wir das Blatt der Schlacht gewendet. Wir werden Eure Hilfe nicht so schnell vergessen.\n\nDa dieser Schläger jetzt tot ist, sollten wir in der Lage sein, Soryns Aue zu halten.\n\nReitet mit uns, {name}. Lasst uns zur Straße und zu Eurem Wildsamen zurückkehren.", sourceObjective = "Reitet mit der Wilden Jagd zu Niya und dem Wildsamen.", completion = "Es ist schön zu sehen, wie die Wilde Jagd wieder zu alter Kraft zurückfindet... und auch, dass Ihr die Geisterwiege nutzen konntet.\n\nJetzt lasst uns den Wildsamen darin zum Winterschlafbecken bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60886] = { id = 60886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sitz des Primus", description = "Das kann kein Zufall sein. Es ist offensichtlich, dass Eure Runenklinge mit dem Sitz des Primus verbunden ist.\n\nIch kenne die Pläne des Primus nicht. Aber es würde mich nicht überraschen, wenn er einen Weg für die Würdigen zurückgelassen hätte, um die Tür zu seinem Sanktum zu öffnen.\n\nDraka wird Euch zum Sitz des Primus bringen. Wenn Ihr den Schlüssel habt, ist uns der Sieg sicher.", sourceObjective = "Geht mit Draka zum Sitz des Primus.", progress = "Was gibt es?", completion = "Wir dürfen die Kämpfe, die vor uns liegen, nicht vergessen. Die Tür muss warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[60887] = { id = 60887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataclysm: Auf ins Abenteuer - Kalimdor", description = "In ganz Azeroth gibt es Leute, die Eure Hilfe benötigen, {name}. Sie kommen aus allen Teilen der Gesellschaft, aber alle suchen ihren Platz in dieser wunderschönen Welt.\n\nWerft einen Blick auf die Tafel mit Befehlen des Kriegshäuptlings und findet heraus, wo Euer Abenteuer wartet!", sourceObjective = "Findet die Tafel mit den Befehlen des Kriegshäuptlings in Orgrimmar.", progress = "Ich kann kaum erwarten, eines Tages Eure Geschichten zu hören.", completion = "So viele Möglichkeiten, so wenig Zeit!\n\nViel Glück da draußen, {name}... Obwohl ich glaube, dass Ihr es nicht braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[60889] = { id = 60889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst: Sie hatte ein Herz aus Stein", description = "Dieser Gegenstand wird die Mittler sicher interessieren.\n\nIhr solltet ihn gemäß der Abmachung mit dem Nachtmarkt direkt zu Ta'xera bringen.\n\nMan wird Euch dafür gebührend entlohnen.", sourceObjective = "Bringt das Gedicht \"Sie hatte ein Herz aus Stein\" zu Ta'xera auf dem Nachtmarkt in Revendreth.\n\nBereitgestellter Gegenstand:", completion = "Ist das ein Stück Papier?\n\n<Ihr übergebt Ta'xera feierlich das Gedicht.>\n\nEin Steingeborenengedicht! Nur sehr wenige Steingeborene drücken Gefühle oder Wünsche aus, die über den Dienst und die Loyalität hinausgehen, die man in sie eingemeißelt hat.\n\nIch werde Spaß... Ich wollte sagen, dies wird ein ausgezeichneter Nachweis für die potenziell vorhandene Tiefe der Steingeborenen sein. Ihr müsst es mir verkaufen!", sourceObjectiveStatus = "unverified-source-field" }
quests[60891] = { id = 60891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataclysm: Auf ins Abenteuer - Östliche Königreiche", description = "In ganz Azeroth gibt es Leute, die Eure Hilfe benötigen, {name}. Sie kommen aus allen Teilen der Gesellschaft, aber alle suchen ihren Platz in dieser wunderschönen Welt.\n\nWerft einen Blick auf den Heldenaufruf und findet heraus, wo Euer Abenteuer wartet!", sourceObjective = "Findet den Heldenaufruf in Sturmwind.", progress = "Ich kann kaum erwarten, eines Tages Eure Geschichten zu hören.", completion = "So viele Möglichkeiten, so wenig Zeit!\n\nViel Glück da draußen, {name}... Obwohl ich glaube, dass Ihr es nicht braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[60898] = { id = 60898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ara'lons Schicksal", description = "{name}, ich habe eine dringende Bitte an Euch.\n\nIn letzter Zeit ist die Wilde Jagd auf eine große Zahl maskierter Fae gestoßen... besonders in der Gegend um den Schwarzdornhain. Ich habe eine Jagdgruppe dorthin geschickt, um die Sache zu untersuchen, aber sie sind noch nicht zurückgekehrt.\n\nAra'lon leitete die Jagd. Ihr habt ihm schon einmal Hilfe angeboten, oder? Ich bitte Euch, dies erneut zu tun.\n\nSucht das Gebiet nach den verschwundenen Jägern ab und erstattet mir Bericht.", sourceObjective = "Such beim Schwarzdornhain nach Ara'lon und dem vermissten Jagdtrupp.", completion = "Seid leise. In der Nähe sind maskierte Fae...", sourceObjectiveStatus = "unverified-source-field" }
quests[60899] = { id = 60899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Nacht in den Wäldern" }
quests[60900] = { id = 60900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivierungsschutz", description = "Die seltensten Bände werden ganz oben in diesem Turm aufbewahrt, geschützt von einem Wesen, das sich Archivar nennt.\n\nDieser stoische Wächter ist unbestechlich. Widerspenstig. Hat keinerlei Interesse an einem fairen Handel!\n\nSein völliger Mangel an Geschäftssinn ist wirklich ziemlich ärgerlich.\n\nTja, nun. Ich fürchte, wir haben keine andere Wahl, als dieses Hindernis zu beseitigen. Wollen wir?", sourceObjective = "Besiegt den Archivar.", completion = "Die Bände sind nicht hier!\n\nDie letzten Worte des Archivars müssen etwas bedeutet haben. Vielleicht ein Hinweis?", sourceObjectiveStatus = "unverified-source-field" }
quests[60901] = { id = 60901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zum Winterschlafbecken", description = "Ihr habt der Wilden Jagd einen großen Dienst erwiesen. Das muss ich irgendwie wiedergutmachen.\n\nDie Schlacht um Soryns Aue hat sich gewendet. Der Schläger ist besiegt und die Streitkräfte der Verseuchten verlieren ihre Stärke.\n\nGestattet uns, Euch zum Winterschlafbecken zu begleiten.\n\nSprecht mich an, wenn Ihr abreisen möchtet.", sourceObjective = "Sprecht mit Ara'lon, um eine Eskorte zum Winterschlafbecken zu erhalten.", completion = "Traumweber hat mir so viel von Eurem sonderbaren Wildsamen erzählt.\n\nIch werde tun, was ich kann, um Euch zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60903] = { id = 60903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krala" }
quests[60904] = { id = 60904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medaillon der Begierde", description = "Das Medaillon der Begierde ruht am Hals der Gräfin.\n\nEs ist eine Machtquelle für sie, aber nicht ihre einzige. Es mit Gewalt an sich zu bringen, würde uns nur einen kurzen Sieg gönnen. Wir müssen weitaus subtiler vorgehen.\n\nZum Glück für uns ist Theotar mit einem Plan zu mir gekommen, aber er wird Eure Hilfe brauchen. Sprecht mit ihm und seht, was Ihr gemeinsam erreichen könnt.\n\nEr stand der Gräfin lange Zeit näher als sonst jemand von uns und ich halte ihn für unseren Experten, was sie angeht.", sourceObjective = "Sprecht mit Theotar.", completion = "Lust auf ein wenig Spionage und Intrigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[60905] = { id = 60905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Wildsamen stärken", description = "Traumweber berichtet von einem Ritual, mit dem die Alpträume dieses Wildsamens gemindert werden können... aber dafür brauchen wir Anima.\n\nEine Seele namens Proglo lebt unter diesem Baum und sammelt Anima für die Pfleger dieses Hains.\n\nEr ist gewaltsam zu Tode gekommen und seitdem eine scheue Seele. Auf Eure jetzige Form wird er nicht positiv reagieren.\n\nIch gewähre Euch die Fähigkeit, die Seelengestalt eines Fuchses anzunehmen. Nähert Euch Proglo in Eurer neuen Gestalt, um sein Vertrauen zu gewinnen und ihn nach Anima zu fragen.", sourceObjective = "Benutzt die Seelengestalt, um Anima von Proglo zu sammeln, und stärkt den Wildsamen mit der gesammelten Anima.", progress = "Ich hoffe, wir können diesem Wildsamen helfen.", completion = "Es wird nicht leicht werden, aber ich kenne einen Ort, an dem wir vielleicht genug Anima finden, um diesem Wildsamen zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60906] = { id = 60906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rechtmäßige Ruhestätte", description = "Ihr habt Euch in den Augen derjenigen, die das letzte Wort über ihn sprechen, wahrlich als <Held/Heldin> bewiesen.\n\nIch danke Euch für die Ehre, ihn halten zu dürfen, wenn auch nur für einen kurzen Moment. Dennoch ist es nur recht und billig, dass Ihr den Speer seiner rechtmäßigen Ruhestätte überantwortet.\n\nTreffen wir uns an der Heldenrast, wo Ihr diesen Akt vollziehen könnt.", sourceObjective = "Überantwortet den Speer der Kalliope seiner rechtmäßigen Ruhestätte in der Heldenrast.", progress = "<Die letzte Ruhestätte des Speers liegt vor Euch.>", completion = "<Legt den Speer der Kalliope in dem Wissen, dass dies nur ein wahrer Held tun kann, in seine rechtmäßige Ruhestätte.>", sourceObjectiveStatus = "unverified-source-field" }
quests[60907] = { id = 60907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berufung des Aufstiegs: Kleia", description = "<Diese Schriftrolle enthält eine Einladung an Kleia, sich Euch und Pelagos auf dem Pfad des Aufstiegs anzuschließen.\n\nEs wäre klug, sie unverzüglich zu ihr zu bringen.>", sourceObjective = "Teilt Kleia mit, dass sie jetzt am Pfad des Aufstiegs teilnehmen kann.", completion = "Zeit, die Flügel zu strecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[60910] = { id = 60910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Masken der Täuschung", description = "Mein Jagdtrupp ist nicht weit von hier in einen Hinterhalt geraten. Ich bin knapp entkommen, aber die anderen wurden tiefer in den Schwarzdornhain verschleppt.\n\nWir müssen sie finden und retten, aber wir sind hoffnungslos unterlegen. Wir müssen uns verkleiden, während wir den Hain durchsuchen.\n\nSeht, ob Ihr dafür irgendetwas Brauchbares findet. Ich brauche noch ein Weilchen, um mich von meinen Wunden zu erholen.", sourceObjective = "Findet zwei Masken der Besessenheit.", progress = "Was habt Ihr entdeckt?", completion = "Jawohl! Wir können diese Masken nehmen, um uns zu verkleiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[60911] = { id = 60911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugschule: Frenetisches Flattern" }
quests[60916] = { id = 60916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückmeldung: Steinkopf", description = "Hallo, bester Kumpel!\n\nKein Fest für mich.\n\n<Steinkopf schüttelt heftig den Kopf.>\n\nWichtige Aufgabe wartet!", sourceObjective = "Fälscht ein Dokument, das Steinkopf erlaubt, seinen Posten für den Gluthof zu verlassen.", progress = "Hallo, bester Kumpel!", completion = "<Steinkopf kratzt sich am Kopf und beäugt das Dokument.>\n\nViele Wachskleckse.\n\n<Steinkopf denkt angestrengt nach und bewegt seine Lippen, während er versucht, die Worte laut auszusprechen.>\n\nÄhm... vielleicht... steht da... Fest für mich mit bestem Kumpel?\n\nToll! Fest für mich mit bestem Kumpel!", sourceObjectiveStatus = "unverified-source-field" }
quests[60920] = { id = 60920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akros" }
quests[60928] = { id = 60928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzdorngefangene", description = "Diese Verkleidungen werden es uns ermöglichen, den Hain unbemerkt zu erkunden, aber hütet Euch vor den Aufsehern. Ihre Drustmagie wird höchstwahrscheinlich unsere Täuschung durchschauen können.\n\nWir müssen den Rest meines Jagdtrupps retten, solange wir das noch können.", sourceObjective = "Findet die vermissten Jäger im Schwarzdornhain.", progress = "Die Drust haben uns so viel genommen...", completion = "Gweyir hat als Einzige überlebt... aber sie ist bereits von der verfluchten Drustmagie betroffen.\n\nWir können sie nicht einfach hierlassen. Nicht so!", sourceObjectiveStatus = "unverified-source-field" }
quests[60929] = { id = 60929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftüberlegenheit" }
quests[60930] = { id = 60930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Senkt Eure Erwartungen", progress = "<Stefan der Wählerische beugt sich dicht zu Euch hinüber und flüstert.>\n\nSchlundgänger, uns gehen die Erfrischungen aus!\n\nZum Glück habt Ihr Euch entschieden, eine so bescheidene... \"Delikatesse\" zu servieren, dass wir fast überall mehr davon finden können.\n\nWenn Ihr Pilze in der Nähe des Gluthofs findet, bringt sie zu mir, und ich lasse sie von den Gräbern klammheimlich auf die leeren Teller legen.", completion = "Eigentlich wäre ich viel wählerischer bei dem, was wir unseren Gästen kredenzen, aber diesem Publikum scheint mein anspruchsvoller Gaumen zu fehlen." }
quests[60932] = { id = 60932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es bleiben nur Schatten", sourceObjective = "Besiegt Heroldin Dalora in der Kathedrale der Dunkelheit.", completion = "Es hat den Anschein, dass die Eliminierung der Heroldin den Vormarsch der Geißel verlangsamt hat.\n\nWir werden wachsam bleiben müssen. Habt Dank für alles, was Ihr getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60934] = { id = 60934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht an Lord Herne", description = "Ich werde alles tun, um Gweyir von diesem Fluch der Drust zu befreien.\n\nLord Herne muss unbedingt erfahren, was meinem Jagdtrupp zugestoßen ist. Bringt ihm diesen Bericht, während ich Gweyir zurück zum Herz des Waldes geleite.\n\nGweyir stand bei dem Hinterhalt unter meinem Befehl... Ich bin für sie verantwortlich. Ich sorge dafür, dass sie sicher nach Hause kommt.", sourceObjective = "Liefert Ara'lons Bericht bei Lord Herne ab.", progress = "Konntet Ihr den verschollenen Jagdtrupp finden?", completion = "Außer Gweyir und Ara'lon hat also niemand überlebt... Das sind schlimme Neuigkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[60935] = { id = 60935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medaillon der Habsucht", description = "Das Medaillon der Habsucht war das Werkzeug der Kuratorin.\n\nMit seiner Macht erhielt sie die Befehlsgewalt über den Katakombendistrikt. Zusammen mit ihrem Wissen aus der riesigen Bibliothek der Sündensteine, die Revendreth im Laufe der Zeit zusammengetragen hat, war die Kuratorin eine Meisterin ihrer Zunft.\n\nAls Denathrius meinen ersten Aufstand niederschlug, warf er mich und die Kuratorin in den Schlund.\n\nDie Kuratorin war allerdings schlau und verbarg das Medaillon, bevor Denathrius handeln konnte. Kommt, lasst uns über Pläne sprechen.", sourceObjective = "Sprecht mit Prinz Renathal.", completion = "Die Kuratorin ist eine der wenigen verbleibenden wahren Venthyr, die während der Gründung Revendreths erschaffen wurden.\n\nIhr Gedächtnis ist gewaltig, aber ihre Zeit im Schlund hat die Reihenfolge dieser Erinnerungen fragmentiert.\n\nSie wird Eure Hilfe benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60945] = { id = 60945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefenechodreizack", description = "<Der Dreizack glänzt im Sonnenlicht.\n\nDas sollte Eure Seelenbande dazu befähigen, ihre Feinde auf dem Pfad des Aufstiegs zu unterbrechen.>", sourceObjective = "Bringt den Tiefenechodreizack zu Paolone.", completion = "Dreizack? Sehr, sehr schön! Bewahre ich gut auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[60946] = { id = 60946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Tiefenechodreizack", description = "<Ihr habt den Bauplan für einen Dreizack gefunden, der Euren Seelenbanden einen Vorteil auf dem Pfad des Aufstiegs schenken könnte.\n\nDactylis sollte Euch dabei helfen können, so einen herzustellen.>", sourceObjective = "Bringt den Bauplan: Tiefenechodreizack zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr einen neuen Bauplan beschafft. Ich freue mich darauf, Euch bei der Herstellung behilflich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60947] = { id = 60947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Amulett der Seelenstärke", description = "<Ihr habt den Bauplan für ein Amulett gefunden, das Eure Seelenbande auf dem Pfad des Aufstiegs verstärken könnte.\n\nDactylis sollte Euch dabei helfen können, so eines herzustellen.>", sourceObjective = "Bringt den Bauplan: Amulett der Seelenstärke zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr einen neuen Bauplan beschafft. Ich freue mich darauf, Euch bei der Herstellung behilflich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60948] = { id = 60948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückmeldung: Die Gräfin", description = "Der Prinz möchte einen Hof abhalten? Na, das dürfte interessant werden.\n\nIhr versteht bestimmt, dass man nichts geben darf, ohne etwas von Wert dafür zu erhalten. Das wäre ein gefährlicher Präzedenzfall, würde unrealistische Erwartungen wecken und Bettler nur ermutigen.\n\nAlso werdet Ihr etwas für mich tun.\n\nHaus Dornfluch ist sehr stolz auf sein neues Maskottchen. Sie stellen es in den Straßen zur Schau und verärgern die anderen Häuser.\n\nStehlt es für mich, aber schiebt es einem der anderen Häuser in die Schuhe.", sourceObjective = "Verkleidet Euch als Mitglied von Haus Zornmeer und stehlt das Maskottchen von Haus Dornfluch.", progress = "Es wäre doch eine wahre Schande, so ein schönes Maskottchen an ein so unwürdiges Haus zu verschwenden.", completion = "Sehr schön. Das sollte die anderen Häuser ablenken, während ich an der Soiree des Prinzen teilnehme.", sourceObjectiveStatus = "unverified-source-field" }
quests[60950] = { id = 60950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Tarnung" }
quests[60955] = { id = 60955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nokos Flöte", progress = "<Noko atmet langsam ein.>\n\nDer Bühnenmanager kann meine Flöte nirgendwo finden.\n\nBeim letzten Mal hatte sie sich einer der ungehobelten Roadies unter den Nagel gerissen.\n\nDiese elenden Gräber machen nichts als Ärger. Und das überall auf dem Fest.\n\nNehmt ihnen meine Flöte ab und ich werde für Eure Gäste spielen.", completion = "<Vorsichtig hält Noko seine Flöte.>\n\nIch fühle mich nur dann ganz wie ich selbst, wenn ich die Flöte meiner Karawane in den Händen halte.\n\nDanke, dass Ihr mir die Gelegenheit gebt, zu spielen." }
quests[60957] = { id = 60957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ansels Glücksgeige", progress = "<Glückspilz Ansel schaut widerwillig von seinem Sündenstein auf.>\n\nMeine Bürde ist noch viel zu schwer.\n\nSolange auch nur eine Sünde auf diesem Stein lastet, bin ich nicht frei von den Gefahren des Schlunds.\n\nZum Glück gefällt meine außergewöhnliche Musik meinen Venthyraufsehern. Und Prinz Renathals Hof zu dienen, wird sich gewiss für mich lohnen.\n\nHolt meine Geige aus den Bandrequisiten bei den Tänzern und ich kann mit meiner öffentlichen Buße beginnen.", completion = "<Ansel dreht seine Violine in den Händen, die im Licht funkelt.>\n\nMöge die Vorstellung beginnen." }
quests[60958] = { id = 60958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur Ihr allein" }
quests[60959] = { id = 60959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade: Auf ins Abenteuer - Scherbenwelt", description = "Die harsche Umgebung der Scherbenwelt stellt sogar erfahrene Abenteurer wie Euch vor eine schwere Herausforderung.\n\nKehrt dorthin zurück und setzt Euer Abenteuer fort!", sourceObjective = "Reist in die Scherbenwelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60960] = { id = 60960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chius Laute", progress = "Ich bin nervös, {name}. Musik entblößt vor aller Augen meine Seele.\n\nUnd obwohl dieser Sündenstein alle an meine dunkle Seite erinnert, hoffe ich, dass die Musik auch mein inneres Licht enthüllt.\n\nLord Garridan in Eurer Botschaft sieht es ebenso. Bei meiner Ankunft war er ausgesprochen nett und voll des Lobes für meine Musik.\n\nIch habe meine Laute bei ihm vergessen. Holt sie mir bitte, während ich mich auf meinen Auftritt vorbereite.", completion = "<Chiu spricht mit der Laute, während sie schnell die Saiten stimmt.>\n\nWas haben diese Gräber dir nur angetan, alte Freundin?" }
quests[60961] = { id = 60961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade: Auf ins Abenteuer - Scherbenwelt", description = "Die harsche Umgebung der Scherbenwelt stellt sogar erfahrene Abenteurer wie Euch vor eine schwere Herausforderung.\n\nKehrt dorthin zurück und setzt Euer Abenteuer fort!", sourceObjective = "Reist in die Scherbenwelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60962] = { id = 60962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King: Auf ins Abenteuer - Nordend", description = "Der Lichkönig wird alles tun, um jedes Lebewesen in Azeroth zu unterwerfen.\n\nKehrt nach Nordend zurück und setzt Euer Abenteuer fort!", sourceObjective = "Reist in die eisigen Lande von Nordend.", sourceObjectiveStatus = "unverified-source-field" }
quests[60963] = { id = 60963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King: Auf ins Abenteuer - Nordend", description = "Der Lichkönig wird alles tun, um jedes Lebewesen in Azeroth zu unterwerfen.\n\nKehrt nach Nordend zurück und setzt Euer Abenteuer fort!", sourceObjective = "Reist in die eisigen Lande von Nordend.", sourceObjectiveStatus = "unverified-source-field" }
quests[60964] = { id = 60964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mists of Pandaria: Auf ins Abenteuer - Pandaria", description = "Im üppigen Grün von Pandaria gibt es noch viele Rätsel zu lösen und Geheimnisse zu lüften, {name}.\n\nKehrt dorthin zurück und setzt Euer Abenteuer fort!", sourceObjective = "Reist in die mysteriösen Gebiete von Pandaria.", sourceObjectiveStatus = "unverified-source-field" }
quests[60965] = { id = 60965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mists of Pandaria: Auf ins Abenteuer - Pandaria", description = "Im üppigen Grün von Pandaria gibt es noch viele Rätsel zu lösen und Geheimnisse zu lüften, {name}.\n\nKehrt dorthin zurück und setzt Euer Abenteuer fort!", sourceObjective = "Reist in die mysteriösen Gebiete von Pandaria.", sourceObjectiveStatus = "unverified-source-field" }
quests[60968] = { id = 60968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlords of Draenor: Auf ins Abenteuer - Draenor", description = "Ihr dürft keine Zeit verlieren, {name}. Das Volk von Draenor braucht immer noch Eure Hilfe!\n\nKehrt dorthin zurück und setzt Euer Abenteuer fort!", sourceObjective = "Reist in die Heimatwelt der Orcs, Draenor.", sourceObjectiveStatus = "unverified-source-field" }
quests[60969] = { id = 60969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlords of Draenor: Auf ins Abenteuer - Draenor", description = "Ihr dürft keine Zeit verlieren, {name}. Das Volk von Draenor braucht immer noch Eure Hilfe!\n\nKehrt dorthin zurück und setzt Euer Abenteuer fort!", sourceObjective = "Reist in die Heimatwelt der Orcs, Draenor.", sourceObjectiveStatus = "unverified-source-field" }
quests[60970] = { id = 60970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion: Auf ins Abenteuer - Verheerte Inseln", description = "Die unendlichen Armeen der Brennenden Legion fallen in unsere Welt ein. Sie drohen Azeroth und alle Bewohner zu vernichten!\n\nKehrt auf die Verheerten Inseln zurück und setzt Euer Abenteuer fort!", sourceObjective = "Reist zu den Verheerten Inseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[60971] = { id = 60971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion: Auf ins Abenteuer - Verheerte Inseln", description = "Die unendlichen Armeen der Brennenden Legion fallen in unsere Welt ein. Sie drohen Azeroth und alle Bewohner zu vernichten!\n\nKehrt auf die Verheerten Inseln zurück und setzt Euer Abenteuer fort!", sourceObjective = "Reist zu den Verheerten Inseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[60972] = { id = 60972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd nach dem Baron", description = "<Das Amulett, das Bolvar Euch gab, flackert schwach rötlich auf und wird dann dunkel.\n\nDamit es bei der Suche nach Darion Mograine nützlich sein kann, müsst Ihr einen Weg finden, seine Kraft wiederherzustellen.\n\nIhr erinnert Euch an ein Gebiet namens Zovaals Kessel, das voller dunkler Magie war.\n\nVielleicht kann die Kraft des Amuletts dort wiederhergestellt werden.>", sourceObjective = "Ladet das Amulett der Reiter auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[60973] = { id = 60973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Phiole des Gleichmuts", description = "<Ihr habt den Bauplan für eine Phiole gefunden, die Euren Seelenbanden einen Vorteil auf dem Pfad des Aufstiegs schenken könnte.\n\nDactylis sollte Euch dabei helfen können, so eine herzustellen.>", sourceObjective = "Bringt den Bauplan: Phiole des Gleichmuts zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr einen neuen Bauplan beschafft. Ich freue mich darauf, Euch bei der Herstellung behilflich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60974] = { id = 60974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phiole des Gleichmuts", description = "<Euer Provostenfreund hat Euch eine zusätzliche Flasche zur Aufbewahrung dieses Tranks gegeben.\n\nDies sollte Eure Seelenbande auf dem Pfad des Aufstiegs im Kampf halten, so wie es Eure Phiole tut.>", sourceObjective = "Bringt die Phiole des Gleichmuts zu Paolone.", completion = "Phiole? Wie reizend! Genau wie Freund! Bewahre ich auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[60975] = { id = 60975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Geistgeschmiedete Aegis", description = "<Ihr habt den Bauplan für einen Schild gefunden, der Euren Seelenbanden einen Vorteil auf dem Pfad des Aufstiegs schenken könnte.\n\nDactylis sollte Euch dabei helfen können, so einen herzustellen.>", sourceObjective = "Bringt den Bauplan: Geistgeschmiedete Aegis zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr einen neuen Bauplan beschafft. Ich freue mich darauf, Euch bei der Herstellung behilflich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60990] = { id = 60990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[60991] = { id = 60991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orrholyn, Herr des Aderlasses" }
quests[60992] = { id = 60992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razkazzar, Herr der Äxte" }
quests[60993] = { id = 60993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zitadelle der Loyalität", description = "Die Medaillons sind die Quelle der Magie für die Krone. Sie sind immer noch dem Willen von Denathrius untergeordnet.\n\nDie Schmiede kann das nicht richten. Aber die Zitadelle der Loyalität.\n\nSie wurde vor Kurzem von den Verschmähten überrannt. Wenn wir die Krone zum Tempel bringen, können wir die Kontrolle des alten Medaillonmeisters brechen.", sourceObjective = "Trefft Euch mit Mikanikos in der Zitadelle der Loyalität.", completion = "Da wären wir. Bin froh, dass Eure Freunde auch da sind.\n\nOhne Hilfe erreichen wir den Tempel nie.", sourceObjectiveStatus = "unverified-source-field" }
quests[60994] = { id = 60994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runter mit ihrer Deckung", description = "Wir können die Krone so verändern, dass sie die Medaillons von Denathrius schändlichem Einfluss läutert.\n\nProblem: Die Verschmähten schützen den Tempel mit einer großen Barriere. Und nur da können wir den Einfluss von Denathrius wirklich brechen.\n\nLösung: Entzieht den Quellen der Barriere die Anima, und sie verschwindet.", sourceObjective = "Entzieht den Barrierenquellen der Verschmähten die Anima.", completion = "Sehr gut.\n\nDie Barriere um den Tempel ist verschwunden. Da müssen wir hin, um die Krone zu reparieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[60995] = { id = 60995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Mangel an Loyalität", description = "Viele Feinde der Bastion sind hier.\n\nWenn wir ihre Reihen ausdünnen, entspannt sich auch die Situation zwischen unseren Reichen.\n\nZeigt keine Gnade.\n\nIch schwinge mich in die Lüfte und helfe von oben. Falls notwendig, kann ich auch Bodenunterstützung leisten.", sourceObjective = "Tötet 15 Verschmähte in der Zitadelle der Loyalität.", completion = "Die Verschmähten sind besiegt? Gut. Je weniger es von ihnen gibt, desto glücklicher bin ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[60996] = { id = 60996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mut im Angesicht der Furcht", description = "Der Weg in den Tempel ist frei. Wir müssen jetzt Mikanikos helfen, den Einfluss des Grafen auf die Krone zu brechen.\n\nBereitet Euch gut vor. Die Magie von Denathrius ist stark und sehr gefährlich.\n\nDas wird nicht einfach.", sourceObjective = "Sprecht mit General Draven, um in den Tempel der Loyalität zu gelangen. Helft dann Mikanikos dabei, die Krone der Ernter zu läutern.", completion = "Nach dem Sieg über das Echo von Denathrius hat mir Mikanikos versichert, dass die Krone geläutert ist.\n\nDies war ein entscheidender Sieg für Revendreth und die gesamten Schattenlande.", sourceObjectiveStatus = "unverified-source-field" }
quests[61050] = { id = 61050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man sieben Medaillons trägt", description = "Ein einzelner Venthyr kann keine sieben Medaillons tragen und über die Macht verfügen, die sie verleihen, und auch keinen Respekt von denen einfordern, die die Medaillons erblicken.\n\nIch schlage vor, dass wir ein Artefakt herstellen, das die Macht der Medaillons fassen kann. Damit konzentriert sich die Macht auf einen Träger.\n\nLeider findet sich in Revendreth keine Handwerkskunst, die solche Mächte kanalisieren könnte. Zumindest keine, die den Träger nicht zu einer Marionette von Denathrius machen würde.\n\nNein, dafür müssen wir die Hilfe eines Reichs beanspruchen, das auf so etwas spezialisiert ist.\n\nDraven hat alle Einzelheiten.", sourceObjective = "Sprecht mit General Draven.", completion = "Nach ausgiebigen strategischen Überlegungen haben der Prinz und ich einen Plan ersonnen, für den es die Hilfe und die Ressourcen von jemanden braucht, gegen den ich einst Schritte im Namen des Meisters unternommen habe.\n\nSchützt Eure Augen. Wir müssen in die Bastion.", sourceObjectiveStatus = "unverified-source-field" }
quests[61051] = { id = 61051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der geistesabwesende Kunsthandwerker", description = "Von allen törichten, fehlgeleiteten, mich noch in den Wahnsinn treibenden...\n\n<Wächterin Kota schnaubt und stampft mit einem Huf auf.>\n\nAber einfach hier herumzustehen, hilft Sha'lor auch nicht weiter. Wir müssen ihn finden und heil zurückbringen.\n\nKommt, wir treffen uns an der Herbstanhöhe. Von dort aus können wir die Höhlen nach einem Lebenszeichen von ihm absuchen.", sourceObjective = "Sucht Meister Sha'lor auf der Herbstanhöhe.", completion = "Nein!\n\nWas auch immer das für eine Bestie war, sie hat Sha'lor!", sourceObjectiveStatus = "unverified-source-field" }
quests[61057] = { id = 61057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Prüfungen geschmiedet", description = "Ihr habt seit Eurer Ankunft im Ardenwald Kraft, Einfallsreichtum und Mitgefühl demonstriert - die Werte, die die größten Jäger auszeichnen.\n\nEs war mir eine Ehre, an Eurer Seite zu kämpfen, {name}. Ich würde nur zu gern als Euer Seelenband weiterkämpfen.", sourceObjective = "Schließt das Ritual der Seelenbindung mit Korayn ab.", completion = "Gemeinsam werden wir den Ardenwald beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61058] = { id = 61058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Träumen gebunden", description = "Ich wusste, dass Ihr jemand Besonderes seid, als Yseras Wildsamen auf Euch reagiert hat. Ohne Euch wäre sie auf ewig verloren - eine Tragödie nicht nur für den Ardenwald, sondern auch für Eure Welt!\n\nSeitdem habe ich erlebt, wie Ihr Euch viele weitere Bürden aufgeladen habt, um Anderen in Not zu helfen. Dank Euch wird der Ardenwald stärker.\n\nEs wäre mir eine Ehre, Euch als Seelenband dabei zu helfen, diese gute Arbeit fortzusetzen.", sourceObjective = "Schließt das Ritual der Seelenbindung mit Traumweber ab.", completion = "Ich bin überzeugt, dass wir gemeinsam den Ardenwald und alle Geister, die in ihm schlummern, retten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[61059] = { id = 61059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückmeldung: Rendel und Knüppelfratze", description = "Hab gehört, der Prinz will Rendel und mich auf seinem Hof sehen. Würd ich ja glatt machen, aber Rendel sagt, ihm fehlt noch der richtige Fummel.\n\nEr braucht einen todschlicken Hut. Aber vom Feinsten, soll ja zu ihm passen.\n\nEr sagt, rote Kopfkerze oder eine von den Faefestmasken ist 'n guter Hut. Oder vielleicht ein festlicher rosa Hut oder eine schlicke Krone des Rechtschaffenen.", sourceObjective = "\"Schlicke\" Hüte können von Spielern hergestellt werden, die das Muster und die richtigen Handwerksfähigkeiten haben.", completion = "Was ein Hut! Rendel wird in aller Munde sein, jawohl.", sourceObjectiveStatus = "unverified-source-field" }
quests[61060] = { id = 61060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporen um die Ohren" }
quests[61061] = { id = 61061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ulfars Rat", description = "Es gibt einen, der vielleicht weiß, wie man den Fluch von Gweyir brechen kann.\n\nIn den Bergen von Drustvar lebt Ulfar, ein alter Dornsprecher, der sich gegen seine Drustgefährten und auf die Seite der Menschen von Kul Tiras gestellt hat.\n\nReist zu seinem Versteck und bittet um seine Weisheit. Er kennt vielleicht die Antworten, die Ihr sucht.\n\nLord Herne und ich werden uns um Gweyir kümmern, sobald sie mit Ara'lon ankommt.", sourceObjective = "Sprecht mit Ulfar in Ulfars Höhle in Drustvar.", completion = "Ihr seid von jenseits des Schleiers gekommen, um meine Weisheit zu suchen? In der Tat eine lange Reise...", sourceObjectiveStatus = "unverified-source-field" }
quests[61062] = { id = 61062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adjutant Dekaris" }
quests[61075] = { id = 61075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Funken Licht", description = "Der Gorgoa ist eine proteische Kraft, angetrieben von Seelen, die aus vielen Welten einströmen. Sie werden von der Quelle des Flusses hierher gespült. Jenen Ort nennt man den Tiegel der Verdammten.\n\nDie starren Augen des Kerkermeisters suchen den Fluss ab und halten Ausschau nach Seelen, die zu fliehen versuchen.\n\nBlendet die Augen, die diese Seelen finden. Schließt sie für immer.\n\nNehmt das hier und tut, was getan werden muss.", sourceObjective = "Besiegt 4 Augen der Verdammnis.", completion = "Gut gemacht, Schlundgänger. Die Augen des Kerkermeisters sind wirklich gefährlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[61076] = { id = 61076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Flammen", description = "Ich kenne den Fluch, von dem Ihr sprecht. Dunkle Magie ergreift Besitz von dem Verstand der Betroffenen.\n\nVor langer Zeit herrschte ein Zaubererkönig namens Gorak Tul über die Drust. Er verdrehte unsere Rituale und führte mein Volk auf den Pfad von Tod und Unterwerfung.\n\nIhr müsst einen Teil seiner Macht beanspruchen, um den Fluch zu brechen.\n\nBringt diesen Fetisch nach Gol Inath und glüht ihn in der Flamme des Vergessens aus. Aber seid auf der Hut... Gol Inath ist ein finsterer und gefährlicher Ort und Gefahr lauert dort in den Schatten.", sourceObjective = "Erfüllt den Drustfetisch mit der Macht von Gorak Tul.", progress = "Die Magie von Gorak Tul verleiht dem Fluch Kraft, und nur seine Magie kann ihn brechen.", completion = "Ich spüre die dunkle Macht von Gorak Tul, die in diesem Fetisch brodelt. Behandelt ihn mit Vorsicht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[61077] = { id = 61077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konfrontation der Sünde", description = "Dank des Überfalls auf Schloss Nathria bietet sich uns eine Möglichkeit.\n\nEine Seele, mächtig und durch die Experimente des Meisters mit finsterer Entschlossenheit erfüllt.\n\nDa dieses Wesen aus Azeroth stammt, hat die Anklägerin um Eure Hilfe bei der Läuterung der Verderbnis gebeten, mit der sein Sündenstein durchdrungen wurde.\n\ndie Anklägerin erwartet Euch in den unteren Ebenen von Sündensturz.", sourceObjective = "Sprecht mit der Anklägerin in Sündensturz.", completion = "Ich stelle keinesfalls die Vermutung an, dass sich alle Sterblichen aus Azeroth gegenseitig kennen.\n\nHat man es allerdings mit einer derart herausfordernden Seele zu tun, hilft auch der leiseste Hauch von Vertrautheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[61079] = { id = 61079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anteil des Kerkermeisters", description = "Die Folterknechte der Schlundgebundenen haben ein Auge für das Elend.\n\nDas von ihnen verursachte Leiden erzeugt mehr Stygia, als sie einsammeln können. Die Überreste schweben lose in der Luft und treiben dann in den Abgrund.\n\nIch habe eigens eine Leitung hergestellt, um diese übriggebliebene Stygia einzufangen. Ihr könnt sie ausborgen, wenn Ihr möchtet.\n\nEs gibt für das Sammeln eine Handvoll erstklassiger Standorte in Calcis. Da Ihr meine Leitung benutzen werdet, können wir uns das teilen, was Ihr bei Eurer Rückkehr vorfindet.", sourceObjective = "Platziert 4 Stygialeitungen an markierten Orten innerhalb von Calcis im Schlund.", completion = "Es ist so befriedigend, zu wissen, dass der Anteil des Kerkermeisters jetzt uns gehört. Gut gemacht, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[61087] = { id = 61087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzögerte Zustellung: Paket vom Alten Tor" }
quests[61088] = { id = 61088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staub zu Staub", description = "Den Schlundgebundenen fallen immer wieder neue Leidensformen ein.\n\nSogar der Boden, auf dem wir uns bewegen, besteht aus Seelen, die zu Staub zerstoßen werden. Mit der Seelenflut, die durch den Gorgoa fließt, wollen die Schlundgebundenen unbedingt ihren Herrschaftsbereich erweitern.\n\nGegenwärtig begraben die Schlundgebundenen Seelen und schaffen neues Terrain aus ihren Qualen. Für einige von ihnen ist es noch nicht zu spät.\n\nBefreit die vergrabenen Seelen und beendet die endlose Ausdehnung des Leidens.", sourceObjective = "Rettet 8 halbvergrabene Seelen in Calcis im Schlund.", completion = "Die seltsamen Formen der Peinigung, die die Schlundgebundenen erfinden, versetzen mich immer wieder in Erstaunen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61092] = { id = 61092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückmeldung: Großmeister Vole", description = "Ich bin beschäftigt, also komme ich gleich zur Sache.\n\nIch kann das nur für Euch tun, wenn Ihr mich ausreichend bezahlt oder unterhaltet.\n\nSo interessant und amüsant der Gluthof auch sein mag, ich verliere jedes Mal Geld, wenn ich nicht hier bin. Abgesehen davon liebe ich ein gutes Gemetzel.\n\nAlso, Münzen oder Tote. Sucht es Euch aus.", sourceObjective = "Überzeugt Großmeister Vole, indem Ihr ihn bestecht oder Spielercharaktere der gegnerischen Fraktion tötet.", completion = "Ist mir recht. Ich werde da sein. Das wird ein schöner Urlaub.", sourceObjectiveStatus = "unverified-source-field" }
quests[61095] = { id = 61095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte von der Unvergänglichen Armee", description = "Eure Bemühungen finden die Zustimmung der Unvergänglichen Armee.\n\nDiese Belohnungen sind eine Anerkennung dieser Bemühungen. Mögen sie Euch in den kommenden Schlachten helfen.", sourceObjective = "Sprecht mit Nalcorn Talsen im Theater der Schmerzen.", completion = "Die Unvergängliche Armee möchte Euch für Eure Hilfe für Maldraxxus danken.\n\nBitte nehmt ein Geschenk in Anerkennung Eurer Dienste für unsere Sache und unsere Streitkräfte an.", sourceObjectiveStatus = "unverified-source-field" }
quests[61096] = { id = 61096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wille der Richterin", description = "Wir werden alle leiden, wenn die Bastion und Maldraxxus sich in einen Krieg stürzen.\n\nDie Nekrolords sind schon seit einiger Zeit isoliert. Ihr müsst in ihr Reich reisen und die Wahrheit hinter dem Überfall in Erfahrung bringen.\n\nObwohl unser Animavorrat nach wie vor niedrig ist, wird er reichen, um Euch den Weg zu öffnen.", sourceObjective = "Trefft Kah-Sher im Ring der Übertragung in Oribos.", completion = "Dieser Platz sollte genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61097] = { id = 61097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte von den Aufgestiegenen", description = "Die Aufgestiegenen möchten Euch für Eure Hilfe für die Bastion danken.\n\nBitte nehmt ein Geschenk in Anerkennung Eurer Dienste für unsere Sache und unser Volk an.", sourceObjective = "Sprecht mit Adjutantin Nikos in Heldenrast in der Bastion.", completion = "Die Aufgestiegenen möchten Euch für Eure Hilfe für die Bastion danken.\n\nBitte nehmt ein Geschenk in Anerkennung Eurer Dienste für unsere Sache und unser Volk an.", sourceObjectiveStatus = "unverified-source-field" }
quests[61098] = { id = 61098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte von der Wilden Jagd", description = "Die Wilde Jagd dankt Euch für Eure Bemühungen, dem Ardenwald zu helfen.\n\nNehmt diese Geschenke als Anerkennung für Eure Hilfe. Mögen sie Euch bei allen Prüfungen helfen, die kommen mögen.", sourceObjective = "Sprecht mit Aithlyn beim Herz des Waldes im Ardenwald.", completion = "Die Wilde Jagd dankt Euch für Eure Bemühungen, dem Ardenwald zu helfen.\n\nNehmt diese Geschenke als Anerkennung für Eure Hilfe. Mögen sie Euch bei allen Prüfungen helfen, die kommen mögen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61099] = { id = 61099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Baine", description = "Natürlich kann ich es nicht wagen, persönlich diesen verfluchten Turm zu betreten.\n\nZwar kann ich Euch nicht genau sagen, wo Euer Verbündeter gefangen gehalten wird, aber ich will Euch ein Geschenk geben, das Euch helfen wird.\n\nVerwendet es in Torghast. Es sollte Euch in die Nähe Eures vermissten Verbündeten bringen. Baine Bluthuf war sein Name, nicht wahr?\n\nEntweder es gelingt Euch, oder Ihr werdet für alle Zeiten in den sich stetig wandelnden Hallen des Turms gefangen sein.\n\nAber das sind nun mal die Risiken, die man auf sich nehmen muss. Viel Glück!", sourceObjective = "Betretet Torghast und sucht nach Baine.", progress = "Ihr habt ihn gefunden!", completion = "Baine zu finden, war keine leichte Aufgabe. Aber Ihr habt den Schrecken des Turms getrotzt und wart erfolgreich.\n\nGut gemacht.\n\nUnd doch, fürchte ich, war das erst der Anfang Eurer Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[61100] = { id = 61100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte vom Hof der Ernter", description = "Eure Unterstützung für unsere Sache ist nicht unbemerkt geblieben. Immer mehr Venthyr im ganzen Reich binden sich an den Hof der Ernter statt an den Meister.\n\nDaher verfügen wir über eine Sammlung von Ressourcen, die Euch nützlich sein könnten und die von Graf Denathrius' ergebensten Anhängern geplündert wurden. Sie warten mit mir zusammen in Dunkelhafen auf Euch.", sourceObjective = "Sprecht mit Herrin Mihaela, um Eure Belohnung zu erhalten.", completion = "Eure Unterstützung für unsere Sache ist nicht unbemerkt geblieben. Immer mehr Venthyr im ganzen Reich binden sich an den Hof der Ernter statt an den Meister.\n\nBitte akzeptiert dieses Zeichen der Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[61102] = { id = 61102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kivarr die Dornsprecherin", description = "In meiner Jugend wurde ich von einer weisen und mächtigen Dornsprecherin namens Kivarr unterrichtet. Ihr Geist hat diese Welt schon vor langer Zeit verlassen, aber ihre Seele ruht vielleicht noch in den Schattenlanden.\n\nKivarr verfügt über gewaltiges uraltes Wissen, das meins bei Weitem in den Schatten stellt. Sie kann Euch vielleicht die Richtung weisen.\n\nSucht sie auf. Bringt ihr den Fetisch. Sie wird wissen, was zu tun ist.\n\nMöge der Wind Euch leiten.", sourceObjective = "Sprecht mit Lord Herne beim Herz des Waldes im Ardenwald.", completion = "Kivarr... Ja, ich habe von jemandem mit diesem Namen gehört. Ara'lon weiß vielleicht, wo Ihr sie finden könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[61103] = { id = 61103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Kreislauf unterbrechen", description = "Die Fessler im Tremaculum sind schreckliche Gesellen.\n\nDie Seelen werden dort gefoltert, bis sie bösartig werden. Sie werden dann als Wächter ausgerüstet, und der Kreislauf geht weiter.\n\nWenn Ihr dafür sorgen wollt, dass der Kerkermeister seine Armeen nicht so schnell aufstellen kann, beginnt an der Quelle.\n\nUnterbrecht den Zyklus am Tremaculum.", sourceObjective = "Besiegt 4 schlundgebundene Fessler und 6 schlundgebunene Scharfschützen im Tremaculum im Schlund.", completion = "Gut gemacht, Schlundgänger. Der Kerkermeister scheint über reichlich Streitkräfte zu verfügen, aber sie sind nicht unerschöpflich.", sourceObjectiveStatus = "unverified-source-field" }
quests[61104] = { id = 61104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grathalax, der Extraktor", description = "Es gibt viele mächtige Leutnants unter den Schlundgebundenen, aber einer ist dem Kerkermeister besonders wichtig.\n\nWeit unter dem Tremaculum lebt Grathalax, der wichtigste Verhörer des Kerkermeisters. Er wird über Leitungen im gesamten Bereich mit Energie versorgt.\n\nSeine Aufgabe ist, den Prozess der Animaextraktion effizienter zu gestalten. Seine Methoden sind... grausam.\n\nIch glaube, wir würden beide vom Ende seiner Existenz profitieren.", sourceObjective = "Besiegt Grathalax unter dem Tremaculum im Schlund.", completion = "Grathalax' Ende wird einen großen Rückschlag für die Infrastruktur des Kerkermeisters bedeuten. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[61105] = { id = 61105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückmeldung: Seuchenerfinder Marileth", description = "Oh! Das klingt nach einer wundervollen Gelegenheit, ein paar Feldstudien vor Ort in Revendreth zu betreiben, Lehrling.\n\nIch freue mich schon auf die Zusammenarbeit mit neuen Kollegen. Wir müssen ihnen zum Dank für die Einladung ein Geschenk mitbringen. Und was wäre wohl passender als ein paar entzückende Schleime?\n\nSucht bitte ein paar der besten Schleime für mich aus, damit wir sie unserem Gastgeber überreichen können. Bringt sie einfach zu Kevin, dann können sie sich anfreunden und gemeinsam auf die Reise gehen.", sourceObjective = "Treibt brodelnde Schlamme zu Kevin, damit Seuchenerfinder Marileth ein Geschenk für den Gluthof hat.", completion = "Das habt Ihr gut gemacht, Lehrling!", sourceObjectiveStatus = "unverified-source-field" }
quests[61107] = { id = 61107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Land der Zwietracht", description = "Es ist unbedingt notwendig, dass Ihr die Beweggründe hinter dem Angriff auf die Bastion erfahrt.\n\nWir brauchen Eure Hilfe, um das Tor zu öffnen. Wenn der Fokus ausreichend aufgeladen ist, rufen wir das Tor nach Maldraxxus und führen es an seine Position.\n\nVon da an lastet das Schicksal dieses Krieges auf Euren Schultern.", sourceObjective = "Aktiviert das Tor nach Maldraxxus.", progress = "Zeit ist kostbar, und jetzt mehr denn je.", completion = "Der Weg ist geöffnet. Die ewigen Schlachtfelder von Maldraxxus erwarten Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[61109] = { id = 61109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückmeldung: Jagdhauptmann Korayn", description = "Ich bin Hauptmann der Wilden Jagd, eine Beschützerin der heiligen Haine. So sehr mir etwas Zerstreuung auch gefallen würde, mein Platz ist hier im Kampf gegen die feindlichen Horden und nicht irgendwo außerhalb des Ardenwalds.\n\nIm Gormnest schlüpfen wieder die Jungen und bald bricht eine Flut von Gormlinglarven über uns herein. Erst wenn diese Gefahr gebannt ist, kann ich meinen Posten verlassen.", sourceObjective = "Beseitigt die Bedrohung durch das Gormnest, indem Ihr Eier zerschlagt, Eierhüter ausschaltet und Gorm tötet, damit Jagdhauptmann Korayn den Gluthof besuchen kann.", progress = "Habt Ihr die Gorm und ihre Eier im Gormnest vernichtet?", completion = "Gut gemacht. Danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[61112] = { id = 61112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunger nach Fleisch", description = "<Das gallegetränkte Tuch riecht tödlich, bei genauerem Hinsehen wirkt es vertraut. Die Insigne des Argentumkreuzzuges ist unverkennbar.\n\nKommandant Gregor wird das umgehend erfahren wollen.>", sourceObjective = "Bringt das halbverdaute Tuch zu Kommandant Gregor im Handelsdistrikt von Sturmwind.\n\nBereitgestellter Gegenstand:", completion = "Dies... Dies ist von einem von uns... von innerhalb der Stadtmauern.\n\nIch werde unsere Patrouillen benachrichtigen. Bleibt wachsam, {name}.\n\nSollte sich die Geißel aus unseren eigenen Reihen erheben, sucht mich umgehend auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[61113] = { id = 61113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kivarrs Höhle", description = "Kivarr... Den Namen habe ich eine Ewigkeit nicht gehört.\n\nFrüher lebte sie in der Nähe des Abendhains im Süden. Ara'lon kennt das Gebiet sehr gut. Ihr solltet ihn mitnehmen.\n\nIch fürchte, die Situation mit Gweyir macht ihm sehr zu schaffen. Vielleicht tut es ihm gut, wenn er mit Euch auf die Jagd geht.", sourceObjective = "Reist zu Kivarrs Höhle im Abendhain im Ardenwald.", completion = "Hier ist es, aber keine Spur von Kivarr...", sourceObjectiveStatus = "unverified-source-field" }
quests[61114] = { id = 61114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunger nach Fleisch", description = "<Das gallegetränkte Leder riecht tödlich, bei genauerem Hinsehen wirkt es vertraut. Die Insigne des Argentumkreuzzuges ist unverkennbar.\n\nKommandant Throgg wird das umgehend erfahren wollen.>", sourceObjective = "Bringt das halbverdaute Leder zu Kommandant Throgg im Tal der Stärke in Orgrimmar.\n\nBereitgestellter Gegenstand:", completion = "Dies... Dies ist von einem von uns... von innerhalb der Stadtmauern.\n\nIch werde unsere Patrouillen benachrichtigen. Bleibt wachsam, {name}.\n\nSollte sich die Geißel aus unseren eigenen Reihen erheben, sucht mich umgehend auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[61123] = { id = 61123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückmeldung: Polemarch Adrestes", description = "Ich muss das Angebot Eures Prinzen höflich ablehnen.\n\nMeine Fähigkeiten werden hier gebraucht, und ich bin nicht besonders gut für die sozialen Anforderungen eines Hofbesuches geeignet.\n\nVielleicht wäre das Paragon der Demut ein besserer Repräsentant der Bastion.\n\nIhr findet ihn vielleicht im Tempel der Demut östlich von hier.\n\nBitte drückt mein aufrichtiges Bedauern aus, dass ich nicht teilnehmen kann.", sourceObjective = "Besorgt Euch Unterstützung vom Paragon der Demut.", completion = "Danke, dass Ihr mich daran erinnert, dass die Pflicht auch Dinge erfordert, die mir unbehaglich sind.\n\n<Polemarch Adrestes salutiert vor Euch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[61124] = { id = 61124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Labyrinthmischling" }
quests[61125] = { id = 61125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boshafte Stygia" }
quests[61129] = { id = 61129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückmeldung: Dromanin Aliothe", description = "Ich diene meiner Königin und halte meinen Schwur, dieses Becken zu beschützen und mich um alle Geister darin zu kümmern.\n\nFrüher hätte mich vielleicht das Fest Eures Prinzen gereizt, aber heute ist diese Art Vergnügung nichts mehr für mich.\n\nMeine Welt wurde vor langer Zeit zerstört und vielleicht habe ich die Freude verloren, die ich dabei empfand, sie mit aller Wildheit zu beschützen. Aber ein Andenken an mein altes Zuhause wäre schön.\n\nIch habe gehört, diese seltsamen Mittler handeln mit ungewöhnlichen Objekten aus anderen Welten.\n\nVielleicht haben sie ja etwas aus meiner?", sourceObjective = "Untersucht die Angebote der Mittler, um zu sehen, ob sich darunter ein Stück aus Aliothes Welt befindet.", progress = "Habt Ihr eine Erinnerung an meine Heimat für mich gefunden?", completion = "Dieser Duft! Den würde ich überall erkennen. Diese Pflanzen standen überall rund um mein Zuhause! Vielen Dank. Ich werde dieses Andenken immer bei mir tragen, um mich an all die glücklichen Zeiten zu erinnern.", sourceObjectiveStatus = "unverified-source-field" }
quests[61130] = { id = 61130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückmeldung: Sika", description = "Hallo, {name}! Sika hilft gern. So viel zu tun.\n\nWürde zum Gluthof gehen, aber zu viel zu tun, was nur Sika tun kann. Tut mir leid.", sourceObjective = "Findet andere im olympischen Dorf, die Sikas Aufgaben übernehmen, damit sie am Gluthof teilnehmen kann.", progress = "Beschäftigt, beschäftigt. Zu beschäftigt. Niemand sonst kann all die Dinge tun.", completion = "Was steht auf Zetteln? Andere brauchen mehr Hilfe von Sika?\n\n<Sika holt tief Luft.>\n\nSika kann das. Sika hilft immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[61135] = { id = 61135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz des Emblems", description = "Mit diesem größten aller Geschenke des Ardenwalds haben wir das letzte Teil für die Rekonstruktion des Emblems des Aufstiegs erhalten.\n\nSorgen wir dafür, dass Weidenblütes Opfer nicht vergebens war.", sourceObjective = "Platziert das Gefäß des Ardenwalds am Emblem des Aufstiegs.", progress = "<Das Gefäß scheint von dem Ort angezogen zu werden.>", completion = "<Weidenblütes Essenz wird das Emblem durchströmen und vervollständigen, sodass die Bastion erneut Aufgestiegene ernennen kann.>", sourceObjectiveStatus = "unverified-source-field" }
quests[61136] = { id = 61136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agonix" }
quests[61139] = { id = 61139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückmeldung: Choofa", description = "Oooh, ein Fest! Ich liebe Feste.\n\nMeine Freunde müssen auch kommen oder es macht einfach nicht so viel Spaß. Fragt sie bitte! Ihr müsst Awool, Rury und Slanknen finden, damit wir zusammen hingehen können.", sourceObjective = "Sorgt dafür, dass alle von Choofas Freunden auf das Fest können.", completion = "Hurra! Wir gehen auf ein Fest.", sourceObjectiveStatus = "unverified-source-field" }
quests[61140] = { id = 61140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dath Rezara" }
quests[61141] = { id = 61141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesreißers Lieblingsspielzeug" }
quests[61143] = { id = 61143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zum Höhlenbau zurück.", description = "Es gibt vielleicht einen Weg, den Fluch der Besessenheit aufzuheben und den Verstand Eurer Freundin zu befreien, aber dafür bedarf es einiger Arbeit.\n\nEs war weise von Ulfar, Euch zu mir zu schicken. Er hat gewusst, dass ein Teil von Gorak Tuls Macht nötig sein wird, aber alle anderen Reagenzien, die wir benötigen, existieren auf Azeroth nicht.\n\nMeine Höhle ist nicht weit von hier. Trefft mich dort und ich helfe Euch, ein Ritual für Eure Freundin vorzubereiten, das den Fluch bricht.", sourceObjective = "Trefft Euch mit Kivarr in ihrer Höhle im Ardenwald.", completion = "Es fühlt sich gut an, nicht mehr in diesem Käfig zu hocken und wieder in meinem Höhlenbau zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[61145] = { id = 61145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bekämpft sie", description = "Unsere Späher berichten, dass Markgraf Gharmal Truppen im Haus der Konstrukte versammelt.\n\nUnsere Nekropole und unsere neuen kyrianischen Verbündeten haben bereits einen Luftangriff begonnen. Ihr müsst unsere Streitkräfte am Boden anführen.\n\nWir treffen uns in der Zerekriss. Wir werden unseren Angriff sofort beginnen.", sourceObjective = "Nehmt das Portal, um Draka an Bord der Zerekriss zu treffen.", completion = "Der Sieg wird unser sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[61146] = { id = 61146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manifestierte Macht", description = "Wie Ihr wisst, können die als Manifestationen bekannten gefährlichen Kreaturen entstehen, wenn wir unsere alten Erinnerungen ablegen. In letzter Zeit gibt es nicht nur immer mehr Manifestationen, sie werden auch immer stärker. Aber ich glaube, sie können uns nach wie vor helfen.\n\nManifestationen bergen große Macht. Diese Macht könnten wir läutern und für unsere Kreationen hier in der Schmiede nutzen. Und indem wir etwas so Negatives in etwas Positives verwandeln, leisten wir gleichzeitig einen noblen Dienst.\n\nEliminiert einfach alle Manifestationen, die Ihr findet, und sammelt ihre Essenz. Das ist alles.", sourceObjective = "Sammelt 15 kondensierte Essenzen von Manifestationen.", progress = "Seid vorsichtig auf Euren Reisen. Manifestationen sollte man im Kampf nie unterschätzen.", completion = "Die sind genau richtig! Geht und dient, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[61148] = { id = 61148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AAAH! Echte Monster!" }
quests[61156] = { id = 61156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federkielholen", description = "Vor langer Zeit übten sich die Aspiranten im Kampf gegen die wilden Kreaturen der Bastion. Aber mit den Zenturionen wurde dieser unstrukturierte Brauch überflüssig.\n\nDie vielen fliegenden Einwohner in diesem Reich sind für ihre Federkiele bekannt. Sie sind leicht und stabil, perfekt für unsere Zwecke.\n\nSammelt bitte alle, die Ihr finden könnt. Es spielt keine Rolle, von welcher fliegenden Kreatur sie stammen.", sourceObjective = "Sammelt 30 Schimmerflugfederkiele von fliegenden Wildtieren.", progress = "Habt Ihr die Federkiele?", completion = "Annehmbare Menge erhalten. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[61157] = { id = 61157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Hörner nehmen", description = "Die gehörnten Tiere der Bastion wurden einst täglich im Aspirantentraining verwendet, allerdings wurden sie mittlerweile von Zenturioneneinheiten abgelöst. Im Laufe der letzten paar Äonen sind ihre Zahlen angeschwollen und müssen ausgedünnt werden.\n\nIhre Hörner sind wichtige Komponenten für unsere Arbeit. Viele Exemplare sind von den Kämpfen abgenutzt und taugen nicht mehr. Ihr müsst beim Sammeln vorsichtig sein.\n\nStellt sie, bezwingt sie und bringt mir ihre Hörner.", sourceObjective = "Sammelt 12 elysische Hörner von gehörnten Wildtieren.", progress = "Wir benötigen so viele Hörner, wie Ihr beschaffen könnt.", completion = "Annehmbare Qualität und Quantität. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[61159] = { id = 61159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todeszeichen", description = "Alle Verschmähten tragen stets Insignien bei sich. Wir vermuten, dass sie mit der Macht aus dem Tempel der Loyalität erfüllt sind, um ihnen für den Kampf gegen uns mehr Kraft zu verleihen.\n\nSammelt diese Insignien von ihren leblosen Überresten ein. Nehmt ihnen ihre Macht, dann werden wir sie für unsere eigenen Zwecke einsetzen.\n\nSo lautet der Wille der Archon und auch der unsere.", sourceObjective = "Sammelt 20 Insignien der Verschmähten von verschmähten Kyrianern.", progress = "Jedes Insigne verschiebt das Gleichgewicht der Macht zu unseren Gunsten.", completion = "Die hier werden uns gute Dienste leisten. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[61161] = { id = 61161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeladene Gäste!" }
quests[61162] = { id = 61162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeladene Gäste!" }
quests[61163] = { id = 61163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeladene Gäste!" }
quests[61164] = { id = 61164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeladene Gäste!" }
quests[61166] = { id = 61166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus alt mach neu", description = "Zenturionen brauchen viele Teile. Aber wir auch!\n\nKofi braucht ihr Metall. Ob von Zenturionen oder vom Boden. Eure Entscheidung!\n\nAber nicht zu beschädigt, ja? Schwer zu putzen!", sourceObjective = "Sammelt 20 Stücke Resonanzlegierung von Zenturionen der Verschmähten oder Zenturioteilen.", progress = "Habt Ihr Metall?", completion = "Mal gegenklopfen... Huuh, klingt echt hart! Wie Kofis Lieblingsmusik!", sourceObjectiveStatus = "unverified-source-field" }
quests[61171] = { id = 61171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungebrochene Bande", description = "Die Drust werden für diesen elenden Fluch bezahlen, den sie über uns gebracht haben.\n\nZu viele Verbündete haben wir schon verloren... zu viele Freunde, um jetzt aufzugeben. Auch wenn wir diejenigen nicht retten können, die der Besessenheit anheimgefallen sind, wir können sie von ihrem Leid erlösen. Ich werde sogleich der Jagd befehlen, alle Besessenen zu töten, die sie sehen.\n\nBringt diesen Bericht bitte zur Winterkönigin. Sie muss all das hier erfahren.\n\nIch danke Euch für Eure Dienste, {name}. Ihr seid <ein wahrer Freund/eine wahre Freundin> und Schild für den gesamten Ardenwald.", sourceObjective = "Bringt Lord Hernes Bericht zur Winterkönigin.", progress = "Was bringt Ihr für Neuigkeiten?", completion = "Wenn die Dornsprecher keinen Weg kennen, um den Fluch aufzuheben, dann gibt es vielleicht wirklich keine Hoffnung mehr für die Besessenen. Das sind wahrlich bittere Neuigkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[61173] = { id = 61173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückmeldung: Mikanikos", description = "Gluthof klingt interessant... aber viel zu tun! Verschmähte haben meine Vorräte geplündert. Alles durcheinander. Keine Ordnung, keine Arbeit. Großes Chaos. Werkstatt kaputt!\n\nHelft mir! Holt Teile. Fast alles kaputt und Ihr? Ihr erkennt Schäden nicht. Bringt mir viel zum Untersuchen. Ich werde das perfekte Teil finden.", sourceObjective = "Helft Mikanikos beim Sammeln potenziell perfekter Teile, damit er seine Konstruktion vollenden und den Gluthof besuchen kann.", progress = "Alle Teile da?", completion = "Perfekt! Das hier! Gesehen? Rest nichts für Konstruktion. Aber für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[61174] = { id = 61174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückmeldung: Baronin Vashj", sourceObjective = "Sammelt die Köpfe furchtbarer Feinde, um sie Baronin Vashj zu präsentieren.", progress = "Wo sind die Köpfe Eurer Feinde?", completion = "<Baronin Vashj nickt zustimmend angesichts der Präsentation der Köpfe, die Ihr vor ihr aufgebaut habt.>\n\nIch denke, ich sollte den Bemühungen des Prinzen lieber mehr Aufmerksamkeit schenken, wenn Ihr sie verstärkt.\n\nAlso schön. Ich werde Prinz Renathal besuchen und an seinem Gluthof teilnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61179] = { id = 61179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiede gut, alles gut", description = "Ewige Schmiede hat wieder Anima?\n\nAh! Ja! Wie aufregend!\n\nIhr müsst gehen. Sucht Schmiedin Selene. Sie wird helfen! So viel zu tun!", sourceObjective = "Sprecht mit Schmiedin Selene in der Ewigen Schmiede.", completion = "Wunderschön, nicht wahr? Ich war mir nicht sicher, ob ich die Schmiede jemals wieder so voller Leben sehen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[61180] = { id = 61180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor dem Lesen verbrennen", description = "Die von Euch geborgene Schriftrolle beschreibt detailliert alle möglichen entsetzlichen Wege, um gefallene Kyrianer in Gharmals Konstrukte zu \"integrieren\".\n\nGleichzeitig ist sie aber auch unvollständig. Es muss noch mehr davon bei den restlichen Anhängern von Fleischnaht geben.\n\nIch habe gesehen, wie sich einige Chirurgen und ihre Lakaien kurz vor unserer Ankunft in die Halle der Ketten zurückgezogen haben. Ich vermute, sie besitzen weitere dieser Schriftrollen.\n\nWir müssen dafür sorgen, dass sie nie wieder gelesen werden.", sourceObjective = "Sammelt 6 von Fleischnahts Entwürfen.", progress = "Dieses grässliche Werk muss vernichtet werden.", completion = "Gut gemacht. Ich werde mich persönlich darum kümmern, dass sie vernichtet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[61182] = { id = 61182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Her mit dem tollen Pollen", description = "Ihr kennt Wirbelblüten?! Drehen sich wie wild im Licht!\n\nWir brauchen Pollen. Nur Pollen, wenn sie blühen!\n\nHolt einen ganzen Haufen! Blumen wachsen in goldenen Feldern. Und drehen sich! Immer rundherum!", sourceObjective = "Sammelt 30 Wirbelblütenpollen in den Ebenen der Bastion.", progress = "Pollen sehr empfindlich. Hält nicht lange!", completion = "So viel! Ja, ja, toll! Perfekt!", sourceObjectiveStatus = "unverified-source-field" }
quests[61189] = { id = 61189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterführende gallertartige Forschung" }
quests[61190] = { id = 61190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aschewelle", description = "Es fühlt sich an, als ob der Schlund selbst lebt... und unsere Anwesenheit zur Kenntnis nimmt.\n\nWir müssen sofort hier weg. Bolvar muss darüber informiert werden, was hier passiert.\n\nIch werde meinen Vater mitnehmen. Führt uns hier raus, {name}. Und zwar schnell.", sourceObjective = "Entflieht dem Schlund meldet euch bei Bolvar in Oribos.", completion = "Und jetzt müssen wir sehen, wie wir Euch und Eure... Partner hier herausbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61193] = { id = 61193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lichterloh", description = "Brauche Licht der Erstgeborenen! Kennt Ihr?\n\nNach Archon benannt! Immer im Wasser. Kofis Lieblingsblume!\n\nLeuchtet ganz hell wenn ausgewachsen. Und kommt an Land! Leicht zu sehen!", sourceObjective = "Sammelt 15 Lichter der Erstgeborenen in Wasserquellen.", progress = "Nur große Blumen! Kleine gehen nicht.", completion = "SO LEUCHTEND! Kofi braucht bald Sonnenbrille!", sourceObjectiveStatus = "unverified-source-field" }
quests[61196] = { id = 61196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimzutat", description = "Manchmal fällt es sogar erfahrenen Kyrianern schwer, zu meditieren. In letzter Zeit häufen sich diese Probleme.\n\nEs gibt ein ganz besonderes Destillat aus unserem reinsten Wasser, mit dem wir unseren Geist sammeln. Ich glaube, das könnte uns auch hier weiterhelfen. Vielleicht als Katalysator für noch stärkere Reaktionen.\n\nWürdet Ihr mir etwas besorgen? Aber Ihr müsst Euch beeilen... die Flüssigkeit wird schnell instabil, wenn Ihr sie aus unseren heiligen Quellen schöpft.", sourceObjective = "Sammelt 10 flüchtige Destillate.", progress = "Habt Ihr das Destillat gefunden?", completion = "Ich werde diese Proben direkt testen! Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[61199] = { id = 61199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffenraffen", description = "Viele Kämpfe hier. Besonders jetzt!\n\nUnd überall Waffen. Zu viele. Können wir nutzen!\n\nGeht zu großem Schlachtfeld und schnappt sie Euch. Besser bei uns aufgehoben!", sourceObjective = "Sammelt 20 gesegnete Waffen von Schlachtfeldern.", progress = "Vorsicht mit dem spitzen Ende!", completion = "Einfach perfekt! Danke Eu-heuch!", sourceObjectiveStatus = "unverified-source-field" }
quests[61209] = { id = 61209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewiges Schlaflied", description = "Obwohl unsere Existenz als Kyrianer endet, wenn wir im Kampf fallen sollten, gibt es große Macht in der Bastion, die Echos unserer ehemaligen Brüder und Schwestern hervorrufen kann.\n\nDiese Erinnerungen streifen ziellos umher. Manche verschreiben sich einer Aufgabe, mit der sie ihre Ewigkeit bei uns verbracht haben: Handwerk, Schutz unserer heiligen Stätten und Ähnliches.\n\nNehmt meine Lyra. Ihre uralte Melodie wird die Erinnerungen zerstreuen und sich gleichzeitig mit der Restenergie unseres Reiches aufladen.", sourceObjective = "Löst 15 Erinnerungen von Kyrianern entlang der Wege der Bastion auf.", completion = "Die Lyra vibriert förmlich vor Macht! Wir werden sie weise nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61217] = { id = 61217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Thela Seelenschlucker", sourceObjective = "Ich erinnere mich an alles! Ich werde nicht länger hier gefangen sein.\n\nErlaubt mir, Euch bei Euren Unterfangen behilflich zu sein, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[61218] = { id = 61218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Grub Grabgut", sourceObjective = "Ihr habt mir 'nen Gefallen getan, also tu ich Euch auch einen und helfe Euch aus.\n\nIch un' meine Schaufel stehen zu Eurer Verfügung.", sourceObjectiveStatus = "unverified-source-field" }
quests[61219] = { id = 61219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Nerith Dunkelschwinge", sourceObjective = "Nach meiner Rache scheint es, als bin ich jetzt ohne Aufgabe.\n\nIch möchte mich Euch anschließen und Eure Feinde in Angst und Schrecken versetzen, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[61220] = { id = 61220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AAAH! Echte Monster!" }
quests[61221] = { id = 61221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Steinschmeißer", sourceObjective = "Mein Sündenstein liegt in letzter Zeit nur noch rum.\n\nIch schätze, wenn ich mit Euch komm, könnt ich ihn vielleicht mal wieder sinnvoll nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61222] = { id = 61222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Kaletar die Heilerin", sourceObjective = "Danke, dass Ihr mich befreit habt, Schlundgänger.\n\nGestattet mir, Eure Freundlichkeit zu erwidern, indem ich Euch helfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[61223] = { id = 61223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Ayeleth der Beraubte", sourceObjective = "Mehr!\n\nLasst mich von Euren Feinden trinken!\n\nLasst mich auf sie los!", sourceObjectiveStatus = "unverified-source-field" }
quests[61226] = { id = 61226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusätzliche Gliedmaßen", description = "Wir können die Pläne der Baronin nicht alleine umsetzen. So ein Vorhaben erfordert eine gut koordinierte Einheit.\n\nDrei haben neben mir Nurakkir aufrechterhalten. Als die Nekropole fiel, fielen zwei meiner Seelenbande mit ihr.\n\nEs bleibt eine Seele, die noch mit meiner verbunden ist. Meine Schwester Xennir hat die Zerstörung überlebt... ist aber von Trauer geplagt.\n\nTrefft Euch mit Xennir. Führt sie durch ihr Trauma und kehrt zurück, wenn sie bereit ist, wieder zu kämpfen.", sourceObjective = "Findet Navigatorin Xennir und unterstützt sie.", completion = "Wir haben so schrecklich gelitten. Ich muss bewahren, was ich noch habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[61227] = { id = 61227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der andere Fuß", description = "Es ist zwecklos, eine Nekropole zu befehligen, wenn niemand zur Hand ist, um sie zu reparieren und in der Luft zu halten. Der Mechaniker von Nurakkir wurde beim Absturz getötet.\n\nDoch aus schlimmen Zeiten ergeben sich auch Möglichkeiten. Vyn hat mir von einer... Auseinandersetzung zwischen den Konstrukten berichtet. Eins von ihnen hat sich gegen die skrupellose Ausschlachtung von Nurakkir geweigert und wurde dafür prompt eingesperrt.\n\nFindet dieses Individuum. Ein feindlicher Deserteur könnte ein Verbündeter werden.", sourceObjective = "Findet Mechaniker Ansid.", completion = "Ihr braucht einen Mechaniker? Na, da habt Ihr Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[61228] = { id = 61228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grubs vermisste Schaufel" }
quests[61230] = { id = 61230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremder Einfluss", description = "Man braucht eine bestimmte Art Magie, um eine Nekropole zu steuern. Der Steuermann der Augen wurde mit Nurakkir ausgelöscht.\n\nAber Baronin Vashj hat mich darüber in Kenntnis gesetzt, wie man eine neue Steuerfrau finden kann.\n\nFolgt mir zum Kommunikationsleuchtfeuer unseres Hauses. Meine Baronin hat mich einen Weg gelehrt, wie wir das richtige Individuum zu uns bringen können.\n\nIch vermute, dass diese Person nicht freiwillig für uns arbeiten will. Ich überlasse es Euch, sie zu überzeugen.", sourceObjective = "Trefft Euch mit Khaliiq an der Kommunikationssäule des Hauses der Augen.", completion = "Ich weiß Eure Pünktlichkeit zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61234] = { id = 61234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinschmeißers Sündenstein" }
quests[61243] = { id = 61243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thelas Gedächtnisstein" }
quests[61246] = { id = 61246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht des Auserwählten", description = "Die Nekropole ist fast in Position. Wir müssen jetzt zuschlagen!\n\nWir müssen Gharmal gemeinsam aus seiner Deckung locken. Schwingt Euch zu mir auf den Roc, und wir lassen die Kolosse die Macht Eurer Runenklinge spüren.\n\nDer Markgraf kann ihre Tode nicht ignorieren. Sobald sie ihren elenden Turm verlassen, können wir sie endgültig erledigen.", sourceObjective = "Zerstört die Gallblähkolosse.", completion = "Welche Macht! Gharmal bleibt keine Wahl, als sich uns zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61248] = { id = 61248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaletars Freiheit" }
quests[61252] = { id = 61252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Fachkraft heraufbeschwören", description = "Wir halten uns an die Befehle meiner Baronin. Lasst uns eine Steuerfrau heraufbeschwören... ganz gleich, wie sehr es sie ärgern mag.\n\nAktiviert das Leuchtfeuer und bereitet Euch auf einen Kampf vor. Die Lichs erachten alle Augen als Feinde. Und Euer Ruf bei ihnen gereicht sicher auch nicht gerade zum Vorteil.", sourceObjective = "Beschwört Steuerfrau Caliroux und besiegt sie.", completion = "Das Vertrauen meiner Baronin in Euch ist wohlverdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[61255] = { id = 61255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückmeldung: Alexandros Mograine", description = "Es wäre mir eine Ehre, Maldraxxus beim Gluthof von Prinz Renathal zu vertreten.\n\nAber bevor ich meinen Posten verlasse, muss ich dafür sorgen, dass meine Kameraden in meiner Abwesenheit sicher sind.\n\nKämpft Euch in die Osseingießerei vor und holt die Waffen von unseren Rivalen dort.\n\nIch lasse sie unter den Truppen verteilen, während ich die Abreise vorbereite.", sourceObjective = "Sammelt 9 Osseinstäbe und 3 Osseinstreitäxte aus der Osseingießerei.", progress = "Habt Ihr die Waffen schon?", completion = "Ein starker Vorteil. Wir gewinnen zusätzliche Waffen und entziehen sie unseren Feinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[61256] = { id = 61256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückmeldung: Kleia und Pelagos", description = "Oh, wunderbar! Vielen Dank für die Einladung zum Gluthof.\n\nWir wollten uns gerade mit einer Meditation läutern. Das ist umso nötiger, wenn wir bald eine Reise unternehmen. Wollt Ihr Euch uns anschließen?", sourceObjective = "Schließt Euch Kleia und Pelagos in der Meditationskammer an und stellt Euch den Erinnerungen Eurer Vergangenheit.", progress = "Habt Ihr Eure Meditation schon vollendet?", completion = "Für mich sind Meditationen immer unglaublich entspannend und produktiv. Findet Ihr nicht? Jetzt sind wir für unsere Reise viel besser gerüstet.", sourceObjectiveStatus = "unverified-source-field" }
quests[61259] = { id = 61259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ayeleths Hunger" }
quests[61262] = { id = 61262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neriths Rache" }
quests[61265] = { id = 61265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Amulett des Eifers", description = "<Ihr habt den Bauplan für ein Amulett gefunden, das Eure Seelenbande auf dem Pfad des Aufstiegs beschleunigen könnte.\n\nDactylis sollte Euch dabei helfen können, so eines herzustellen.>Ihr erlernt:", sourceObjective = "Bringt den Bauplan: Amulett des Eifers zu Dactylis.", sourceObjectiveStatus = "unverified-source-field" }
quests[61269] = { id = 61269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Amulett der Hartnäckigkeit", description = "<Ihr habt den Bauplan für ein Amulett gefunden, das Eure Seelenbande auf dem Pfad des Aufstiegs dazu ermutigen könnte, durchzuhalten.\n\nDactylis sollte Euch bei seiner Herstellung behilflich sein können.>", sourceObjective = "Bringt den Bauplan: Amulett der Hartnäckigkeit zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr einen neuen Bauplan beschafft. Ich freue mich darauf, Euch bei der Herstellung behilflich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[61272] = { id = 61272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Amulett der Zwietracht", description = "<Ihr habt den Bauplan für ein Amulett gefunden, das den Feinden Eurer Seelenbande auf dem Pfad des Aufstiegs Schaden zufügen könnte.\n\nDactylis sollte Euch dabei helfen können, so eines herzustellen.>", sourceObjective = "Bringt den Bauplan: Amulett der Zwietracht zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr einen neuen Bauplan beschafft. Ich freue mich darauf, Euch bei der Herstellung behilflich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[61303] = { id = 61303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es regnet Funken" }
quests[61304] = { id = 61304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Kyrianische Schmiedeausrüstung", description = "<Ihr habt einen Bauplan für ein Reparaturset entdeckt, mit dem man ein Rüstungsteil unterwegs reparieren kann.\n\nDactylis sollte Euch dabei helfen können, so ein Set herzustellen.>", sourceObjective = "Bringt den Bauplan: Kyrianische Schmiedeausrüstung zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr einen neuen Bauplan beschafft. Ich freue mich darauf, Euch bei der Herstellung behilflich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[61313] = { id = 61313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Kythekios", sourceObjective = "Ich kann wieder kämpfen! Erlaubt mir, meine Kampfkraft gegen Eure Feinde einzusetzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[61314] = { id = 61314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME - SCS", description = "Ihr werdet ein Gefäß brauchen, um die Anima aufzunehmen, die Ihr sammeln müsst. Es muss Euch gleichzeitig aber auch erlauben, diese Anima zu kanalisieren.\n\nEs gab vor Ewigkeiten einmal solche Geräte, aber in letzter Zeit sind sie viel seltener geworden.\n\nBei meinen Reisen durch den Schlund habe ich einmal eines gesehen. Es befindet sich in der (AREA NAME) im Besitz von (CREATURE).\n\nIhr werdet Glück brauchen, um es zu bergen.", sourceObjective = "Beschafft den Animafokussierer.", sourceObjectiveStatus = "unverified-source-field" }
quests[61317] = { id = 61317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Teliah", sourceObjective = "Dieser neuen Waffe fehlt etwas: das Blut meiner Feinde! Erlaubt mir, dies zu korrigieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[61318] = { id = 61318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Telethakas", sourceObjective = "Der Ehre wurde genüge getan. Nun will ich einem neuen Meister dienen. Meine Wahl fällt auf Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[61319] = { id = 61319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Hala", sourceObjective = "Ihr habt mir mein Schwert zurückgebracht. Ich stehe in Eurer Schuld, Schlundgänger. Erlaubt mir, Euch weiterhin zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61320] = { id = 61320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Molako", sourceObjective = "Ich kann Euch nicht genug für meine Freiheit danken. Ich würde Euch gern bei Euren kommenden Aufgaben unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61321] = { id = 61321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Ispiron", sourceObjective = "Ich bin wiederhergestellt. Ohne Euch wäre das nicht möglich gewesen. Ich werde meine Kräfte in Eure Dienste stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61322] = { id = 61322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kythekios' Gedächtnisstein" }
quests[61323] = { id = 61323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seht, was Ihr getan habt", description = "Wir haben so viele Kämpfer wie möglich versammelt. Ich hoffe, das wird reichen.\n\nIn den Ruinen unserer Nekropole wartet noch eine letzte Herausforderung. Die Anführerin der Plünderung nennt sich Gorgantus.\n\nUm das zu wahren, was uns noch bleibt, muss sie vernichtet werden.\n\nFührt Ihr den Angriff an, die Augen werden Euch folgen. Wir werden unser Zuhause wieder einnehmen.", sourceObjective = "Tötet Gorgantus die Ausweiderin.", completion = "Ich werde wieder Akareks Willen in die Tat umsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61330] = { id = 61330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teliahs gestohlener Speer" }
quests[61331] = { id = 61331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der verlorenen Seelen", description = "Immer mehr Seelen strömen in den Schlund. Solange das nicht aufhört, müssen wir so viele wie möglich retten.\n\nDer Kerkermeister verdreht den Kreislauf von Leben und Wiedergeburt. Das darf so nicht weitergehen. Wir müssen seine Pläne durchkreuzen.\n\nKehrt zum Schlund zurück und rettet, so viele Ihr könnt.", sourceObjective = "Rettet Seelen im Schlund.", completion = "Oh, wunderbare Neuigkeiten!\n\nIch werde dafür sorgen, dass diese Seelen hier im Ardenwald gut versorgt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[61332] = { id = 61332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der verlorenen Seelen", description = "Immer mehr Seelen strömen in den Schlund und umgehen die natürliche Ordnung der Schattenlande.\n\nDer Kerkermeister verwehrt diesen Seelen ihre rechtmäßige Ewigkeit. Nur Ihr, <Schlundgänger/Schlundgängerin>, könnt die Dinge wieder in Ordnung bringen.\n\nKehrt zum Schlund zurück und rettet, so viele Ihr könnt.", sourceObjective = "Rettet 5 Seelen aus dem Schlund.", completion = "Gut gemacht. Ihnen wurde eine wahrhaft grausame Existenz erspart.", sourceObjectiveStatus = "unverified-source-field" }
quests[61333] = { id = 61333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der verlorenen Seelen", description = "<Schlundgänger/Schlundgängerin>, ich bin sicher, Ihr habt die Seelen, die weiterhin in den Schlund strömen, mit eigenen Augen gesehen.\n\nWir müssen jetzt handeln und dem Kerkermeister die Macht entziehen, indem wir ihm so viele Seelen wie möglich verwehren. Diese Macht gehört den Nekrolords.\n\nIch werde Eure Bemühungen lenken, diese Seelen zu retten, und dabei helfen, für sie einen Platz in den Armeen von Maldraxxus zu finden.\n\nKehrt zum Schlund zurück und rettet diejenigen, die Ihr retten könnt.", sourceObjective = "Rettet Seelen im Schlund.", completion = "Ausgezeichnet, Schlundgänger. Unsere Armeen hier werden mit jeder Seele, die Ihr zurückbringt, stärker werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[61334] = { id = 61334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der verlorenen Seelen", description = "Immer mehr Seelen strömen in den Schlund.\n\nIhre Anima, das Lebensblut der Schattenlande, entschwindet mit diesen Seelen, um den Kerkermeister zu nähren. Ihr habt mich aus dem Schlund gerettet. Ich sehe keinen Grund, warum Ihr diesem Abgrund nicht noch mehr Seelen entreißen könnt.\n\nBringt mir Seelen, die Ihr aus dem Schlund rettet, und ich sorge dafür, dass sie eine bessere Verwendung finden. In Revendreth haben sie wenigstens eine Chance auf Erlösung.", sourceObjective = "Rettet Seelen im Schlund.", completion = "Eine ausgezeichnete Sammlung von Seelen, nicht zu gebrochen, nicht zu ausgelaugt und nicht zu unschuldig.\n\nSeid unbesorgt, ihr Schicksal liegt besser in unseren Händen als in denen des Kerkermeisters.", sourceObjectiveStatus = "unverified-source-field" }
quests[61335] = { id = 61335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käfigsturm", description = "Ihr sucht einen Mechaniker, wie? Ihr habt ihn schon gefunden!\n\nIch schufte schon seit Ewigkeiten an einer neuen Nekropole. Als Nurakkir unterging, war das die perfekte Gelegenheit für uns! Wir wollten uns Teile aus dem Wrack sichern, aber diese Grobiane haben mich eingesperrt, als ich ihre Methoden kritisiert habe.\n\nAber jetzt braucht Ihr doch Hilfe, oder? Da bin ich genau Euer Konstrukt!\n\nWenn Ihr mich hier rausholt, habt Ihr Euren Mechaniker!", sourceObjective = "Befreit Ansid den Mechaniker mithilfe von Tacks Schlüssel aus seinem Käfig.", progress = "Könnt Ihr mich irgendwie befreien?", completion = "Danke für die Rettung! Ihr habt was gut bei mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[61337] = { id = 61337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marsch des Ewigen Beschützers" }
quests[61340] = { id = 61340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telethakas' Rache" }
