quests[61347] = { id = 61347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Molakos Freiheit" }
quests[61348] = { id = 61348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halas Schwert" }
quests[61351] = { id = 61351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralter Sündenstein (+Förmlich)", progress = "<Prinz Renathal betrachtet den uralten Sündenstein, den Ihr mitgebracht habt, mit großem Interesse.>\n\nWo habt Ihr nur diesen alten Sündenstein gefunden?", completion = "Ich weiß wirklich zu schätzen, dass Ihr mir diesen Sündenstein bringt, {name}.\n\nEr ist beinahe so alt wie ich." }
quests[61352] = { id = 61352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle werden verschlungen" }
quests[61353] = { id = 61353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle werden verschlungen" }
quests[61354] = { id = 61354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückmeldung: Lady Mondbeere", description = "Natürlich bin ich dabei, {name}. Der Gluthof klingt nach einer Menge Spaß!\n\nAber ich kann nicht ohne ein Geschenk hingehen!\n\nGastgeschenke sind eine wichtige Tradition vieler Welten und ich fühle mich verpflichtet, meinem Gastgeber und den anderen Gästen etwas Angemessenes zu überreichen.\n\n<Lady Mondbeere unterdrückt ein Schmunzeln.>\n\nAus Gründen, die Euch bestiiiimmt nicht interessieren, brauche ich eine stabile aber hübsche Ranke, einige gefährliche, aber wunderschöne Blüten und natürlich ein paar Gormpheromone.\n\nFür jemanden mit Euren Talenten ein Kinderspiel.", sourceObjective = "Sammelt 3 Silberherzrankenblätter, 9 blühende Peitschensporne und eine Gormpheromondrüse.", progress = "Habt Ihr alle Teile für mein Geschenk gefunden?", completion = "Das wird lustig. Äh, ich meine festlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[61355] = { id = 61355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regel 2: Möglichst nicht auffallen", description = "Auch wenn Ihr vielleicht mit Euren kostbaren Seelen im Schlepptau abreisen möchtet, müssen wir erst noch weitere Angelegenheiten regeln.\n\nDas Auge des Kerkermeisters ist auf Euch gerichtet. Und das verheißt für keinen von uns Gutes.\n\nNehmt dieses Gerät. Ihr werdet meine Zauberschutze verstärken, damit er mich nicht auch noch bemerkt.\n\nDas Letzte, was ich brauche, ist <ein lauter, uneleganter Sterblicher, der/eine laute> unelegante Sterbliche, die; noch mehr Aufmerksamkeit auf mich lenkt. Ich kann schließlich nicht zulassen, dass der Kerkermeister mich gefangen nimmt.\n\nIch bin viel zu wertvoll.", sourceObjective = "Verstärkt 4 Seelenschutzzauber.", completion = "Das sollte reichen, um uns vor dem Blick des Kerkermeisters zu verbergen.\n\nIch brauche Euch lebendig. Wenigstens vorläufig.\n\nUnd jetzt wieder an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[61356] = { id = 61356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echthra, Dame des Hasses", progress = "Wir haben Kontakt zu einem Mitglied des ehemaligen Hauses der Augen in Maldraxxus aufgenommen. Sie ist eine begabte Schützin und wäre eine angemessene Gegnerin für Eure Seelenbande.\n\nAls Gegenleistung für ihre Erinnerung möchte sie ein spezielles Salbungsöl, das in Zeremonien der Kyrianer verwendet wird.", completion = "Das sollte genügen. Gut gemacht." }
quests[61357] = { id = 61357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abklingender Hass", description = "Wie vereinbart dürft Ihr meine Erinnerung für die gewünschte Prüfung verwenden.\n\nAber seid gewarnt, <Sterblicher/Sterbliche>, auch als Echo meiner körperlichen Form werde ich ohne zu zögern angreifen. Erwartet keine Gnade, denn ich werde Euch keine gewähren.\n\nIhr habt mir heute einen großen Dienst erwiesen. Kümmert Euch nun um Eure Belange.", sourceObjective = "Fangt Echthras Erinnerung ein.", completion = "Ein guter Fang. Ihr habt getan, was getan werden musste. Ich werde Adrestes über dieses Spionagenetzwerk unterrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[61358] = { id = 61358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alderyn und Myn'ir", progress = "Die Wilde Jagd besteht aus Fährtenlesern und Jägern von unglaublicher Macht, die den Ardenwald vor Mächten schützen, die diesen Ort der Ruhe zerstören wollen.\n\nWir haben uns an ein Duo gewandt, das sich bereit erklärt hat, seine Erinnerungen zur Verfügung zu stellen, wenn Ihr den beiden helft, ein lästiges Ziel auszuschalten.", completion = "Dieser Speer sollte genau das Richtige für sie sein, um ihre Beute zur Strecke zu bringen." }
quests[61359] = { id = 61359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht des Primus", description = "Als Nekrolord ist es Eure Pflicht, die Schattenlande zu verteidigen. Um einen solchen Dienst zu verrichten, gewährt uns der Primus seine Kraft.\n\nStellt Euch auf den Altar des Primus. Lasst seine Macht zu Eurer werden.", sourceObjective = "Kniet vor dem Primus nieder und erhaltet seine Macht!", progress = "Es ist eine große Ehre, über die Macht des Primus zu gebieten.", completion = "Ihr seid ein Nekrolord, {name}. Wir bleiben standhaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[61360] = { id = 61360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dankbarkeit der Jagd", description = "Dank Eurer Hilfe, <Gesandter/Gesandte> der Kyrianer, sind die Wälder von Ardenwald sicherer geworden.\n\nAls Belohnung für Eure Hilfe werden wir Euch gestatten, unsere Erinnerung einzufangen. Es ist eine Ehre, ausgewählt zu werden, um bei der Ausbildung der mächtigen Krieger der Bastion zu helfen.\n\nWann immer Ihr bereit seid.", sourceObjective = "Fangt Alderyns und Myn'irs Erinnerungen ein.", completion = "Die Wilde Jagd besteht aus unglaublichen Jägern. Ich bin gespannt darauf, was Eure Seelenbande lernen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[61361] = { id = 61361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nuuminuuru", progress = "Die Tirnenn des Ardenwalds sind uralte, mysteriöse Fae, die uns viel beibringen können. Sie meiden Konflikte und Kämpfe, sind jedoch mächtige Gegner, wenn man sie verärgert.\n\nEine der Tirnenn hat sich als Lehrerin für Eure Seelenbande angeboten. Gemeinsam mit ihrer Feenschar kann sie Euch viele alternative, doch entscheidende Lektionen beibringen.", completion = "Die Bitte war zwar ziemlich unkonventionell, ich bin mir aber sicher, dass dieser Brunnen genau das ist, was sie benötigt." }
quests[61362] = { id = 61362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feenpflegerin", description = "Tirnenn und Feen unterscheiden sich in vielerlei Hinsicht.\n\nTirnenn sind geduldig und gleichmütig wie die Bäume, die in die Höhe wachsen und uns schützen. Feen wiederum tanzen und springen und scheuen sich nicht, frei heraus zu sagen, was sie begehren.\n\nTrotz dieser Unterschiede halten wir zusammen. Lernen, wachsen, entwickeln uns.\n\nWir werden Euch und den Euren helfen, ebensolche symbiotische Gelassenheit zu erlangen.", sourceObjective = "Fangt Nuuminuurus Erinnerung ein.", completion = "Wie es scheint, habt Ihr bereits von den Tirnenn gelernt. Ich bin gespannt, was sie Euch sonst noch beibringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[61363] = { id = 61363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manischer Mortimer", progress = "Ein Alchemist in Maldraxxus schwört, dass seine neueste Kreation einfach revolutionär ist, aber es fehlt immer noch ein wichtiger Katalysator.\n\nWenn wir ihm helfen, ist er einverstanden, dass Ihr seine Erinnerung für den Pfad einfangt.", completion = "<Dactylis inspiziert den Katalysator.>\n\nGute Arbeit. Das sollte unserem studierten Freund gefallen." }
quests[61364] = { id = 61364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trieft vor Möglichkeiten", description = "Und mich haben sie verrückt genannt! Tun sie eigentlich immer noch!\n\nAh, aber niemand von ihnen verfügt über den Scharfsinn von Doktor James Mortimus aus dem immer noch sehr intakten Haus der Seuchen! Oder sein charmantes Lächeln! Narren!\n\nMit dem Katalysator, den Ihr mir so freundlicherweise gebracht habt, <werter/werte>... was auch immer Ihr auch seid... auf keinen Fall <kein Kyrianer/keine Kyrianerin>...\n\nIch schweife ab!\n\nWir kommen gleich zu was immer Ihr auch wolltet, aber jetzt ist es Zeit für WISSENSCHAFT! Kommt, kommt, bestaunt die wunderbaren Früchte all meiner Mühen!", sourceObjective = "Helft dem Manischen Mortimer bei seinem Experiment und fangt dann seine Erinnerung mit dem Seelenspiegel ein.", completion = "Es scheint, als hättet Ihr Erfolg gehabt. Gut gemacht, wie immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[61365] = { id = 61365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splitterborkalptraum", progress = "Ritualisten der Drust haben eine schreckliche Kreatur erschaffen, die unsere nahen Verbündeten im Ardenwald bedroht.\n\nWenn es uns gelingt, uns einen Weg zu der Kreatur zu bahnen und sie mit einem Prätorresonanzsignal zu markieren, können wir sowohl ihre Essenz für den Pfad einfangen als auch sicherstellen, dass sie dem Reich der Fae keinen Schaden zufügt.", completion = "Möge den Drust heute ein schwerer Schlag versetzt werden." }
quests[61366] = { id = 61366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktische Operation", description = "Euer Ziel liegt in der Nähe des Eichengehölzes im Ardenwald in der Ältestenwehr. Seid auf der Hut, denn in der Nähe lauern mächtige Streitkräfte der Drust.\n\nSobald Euer Ziel in Sichtweite ist, aktiviert das Signal und beschützt die eintreffenden Prätoren, die sich bemühen werden, die Bestie zu unterwerfen. Ihr könnt erst dann ihre Erinnerung einfangen, wenn sie vollständig außer Gefecht gesetzt ist.\n\nBeeilt Euch und viel Glück. Folgt dem Pfad.", sourceObjective = "Aktiviert das Prätorresonanzsignal beim Splitterborkalptraum in der Ältestenwehr im Ardenwald, beschützt die Prätoren und fangt die Erinnerung des Splitterborkalptraums ein.", completion = "Die Erinnerung des Alptraums wird ein außerordentlich starker Gegner sein. Möge seine körperliche Gestalt weiter in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61367] = { id = 61367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thran'tiok", progress = "Maldraxxus ist die Heimat der mächtigsten Anwender von Anima in den Schattenlanden, der Lichs vom Haus der Rituale.\n\nSich gegen einen Lich zu üben würde Eure Seelenbande um wichtige Lektionen und Taktiken reicher machen. Diese können sie dann einsetzen, wenn sie jemals einem böswilligen Anwender von Magie gegenüberstehen.", completion = "Dieser Kristall wird Euch helfen, die gesuchte Erinnerung zu finden und einzufangen." }
quests[61368] = { id = 61368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geklaute Phylakterien", description = "Dieses Phylakterium enthält die Seele von Thran'tiok... ihre Essenz.\n\nBringt schnell zu Ende, was Ihr zu erledigen habt. Ich muss dieses Stück ihrer Seele fortbringen, bevor sie zurückkehrt.\n\nIhre Paranoia wird wahrlich ihr Ende sein.", sourceObjective = "Fangt Thran'tioks Erinnerung mit dem Phylakterium der Schmerzen ein.", completion = "Ein Glück, dass Ihr die Erinnerung der Lich einfangen konntet, ohne ihr selbst zu begegnen.\n\nSolch mächtige Wesen dürfen nicht unterschätzt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[61369] = { id = 61369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craven Korinth", progress = "Einer von Denathrius' ehemaligen Untergebenen, Craven Korinth, wird als so gefährlich betrachtet, dass er nicht einmal ihren lichtdurchfluteten Glutdistrikt frei durchstreifen darf.\n\nSeine Erinnerung würde im Kolosseum den perfekten Gegner abgeben. Wir brauchen nichts weiter als einen Schlüssel, um ihn aus seinem Kerker zu befreien.", completion = "Ein Glück, dass ich die Entwürfe für diesen Venthyrschlüssel über all die Jahrtausende aufbewahrt habe. Ihn zu besorgen, war nicht einfach." }
quests[61370] = { id = 61370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine andere Möglichkeit", description = "Korinth wird seine Erinnerung nicht freiwillig hergeben. Ihr müsst ihn ausreichend schwächen, bevor er sich der Energie des Seelenspiegels geschlagen gibt.\n\nIhr findet ihn tief verborgen in der Austrocknung in Revendreth, weggesperrt mit den anderen lichtscheuen Venthyr. Wenn Ihr ihn befreit, wird er Euch gewiss in blindem Zorn angreifen.\n\nUnterwerft ihn und raubt ihm seine Erinnerung. Dann kann er sich wieder unter Seinesgleichen tummeln.", sourceObjective = "Unterwerft Craven Korinth in der Austrocknung in Revendreth und raubt ihm seine Erinnerung.", completion = "Noch ein weiterer wertvoller Besitz. Korinth wird Euch ein würdiger Gegner sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[61371] = { id = 61371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Athanos", progress = "Für Eure letzte Prüfung auf dem Pfad müsst Ihr Euch einem alten Freund aus den ersten Momenten in diesem Reich stellen: Athanos.\n\nEs ist viele Jahrtausende her, dass dieser mächtige Goliath zusammen mit seinem legendären Speer, dem Demutswächter, die Arena betreten hat. Als er uns verließ, wurde seine Waffe nach alter Tradition zerlegt.\n\nSollte Athanos erneut einen Blick auf den Demutswächter werfen können, lässt er sich bestimmt überzeugen, erneut die Arena zu betreten. Wir haben den zerbrochenen Speer, benötigen aber noch Materialien, um ihn zu reparieren.", completion = "Möge Athanos endlich wieder zu uns zurückkehren." }
quests[61372] = { id = 61372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu ihm", description = "Auch mit dem Demutswächter in Eurer Hand müsst Ihr Euch als <würdiger Gegner/würdige Gegnerin> beweisen, wenn Ihr Athanos überzeugen wollt, zum Pfad des Aufstiegs zurückzukehren.\n\nTretet in den Ring und führt den Speer gegen ihn zu Felde. Selbst mit der Macht des Speers könnt Ihr ihn niemals bezwingen, aber er sollte zumindest das gewaltigen Aufstampfen des Goliaths parieren.\n\nHaltet seinen unablässigen Angriffen lange genug stand, und er wird Euch sicherlich gestatten, seine Erinnerung einzufangen.", sourceObjective = "Blockt Athanos' kraftvolles Stampfen 6 Mal und fangt seine Erinnerung ein.", completion = "<Pure Überraschung steht Dactylis ins Gesicht geschrieben.>\n\nIhr habt es tatsächlich geschafft? Nun gut! Ein wahrhaft würdiger Gegner.", sourceObjectiveStatus = "unverified-source-field" }
quests[61373] = { id = 61373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azaruux, der Weltenender", description = "Ihr müsst sofort handeln!\n\nEin Verschlinger von gewaltiger Stärke hat einen Riss im Kolosseum geöffnet und droht nun, es komplett zu verschlingen! Unsere wenigen Kämpfer können die Kreatur kaum bändigen.\n\nWenn wir diesen Schrecken nicht aufhalten, wird er sich durch die ganzen Spitzen arbeiten. Nehmt Euch in dem Gebiet so viel Anima, wie Ihr könnt, und haltet ihn auf.\n\nSobald die Bedrohung abgewendet ist, nehmt diesen Ersatzspiegel und fangt seine Erinnerung ein, damit wir für zukünftige Begegnungen mit seiner Art besser gewappnet sind.", sourceObjective = "Absorbiert Anima, um die Animakonfluxe zu aktivieren und Azaruux zu unterwerfen. Fangt anschließend seine Erinnerung ein.", completion = "Eine heroische Tat! Wir werden viel aus dem Kampf gegen diese Bestie lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61388] = { id = 61388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gemeinsame Reise", description = "Die Bindung der Seelen ist nur der erste Schritt.\n\nIm Laufe der Zeit wird unser Band stärker und manifestiert sich in Form von erstaunlichen neuen Fähigkeiten!\n\nUm Euch diese neuen Kräfte zunutze zu machen, müsst Ihr nur Eure Hand auf die Schmiede der Bande legen. Dafür ist kein Preis zu zahlen. Die einzige Beschränkung ist Eure Verbindung zu den Nekrolords.", sourceObjective = "Aktiviert einen Seelenbandbonus, indem Ihr die Schmiede der Bande benutzt.", progress = "Dieses Gerät ist nur ein Medium für die Stärke, die in uns beiden schlummert.", completion = "Mögen wir uns in den bevorstehenden Schlachten als würdige Verbündete erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61391] = { id = 61391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge des Kerkermeisters", description = "<Die Luft um Euch herum steht still. Durchdringende Kälte ergreift von Euch Besitz. Ihr hört eine Stimme.>\n\nJa... Ich erinnere mich an Euch...\n\nGlaubt Ihr, ich würde zulassen, dass Ihr Euch erneut meinem Zugriff entwindet?\n\nNein. Der Schlund untersteht mir. Alles, was Euch hier widerfährt, wird geschehen, weil ich es so will.\n\nDer Tod wird Euch holen, <Sterblicher/Sterblicher>. Wohin Ihr auch geht, mein Auge ist auf Euch gerichtet.Ihr erlernt:", sourceObjective = "Sprecht mit Ve'nari über das, was Ihr gerade gehört habt.", sourceObjectiveStatus = "unverified-source-field" }
